cd "/c/Users/edmem/OneDrive/Desktop/Nxeon/Marketing website redesign" && mkdir -p scripts public src/app src/components src/lib && cat > scripts/build-globe-dots.mjs <<'EOF'
// Samples a Fibonacci sphere and keeps the points that fall on land.
// Output feeds the dot-matrix globe (public/globe-dots.json).
import { readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { feature } from "topojson-client";
import { geoContains } from "d3-geo";

const require = createRequire(import.meta.url);
const topo = JSON.parse(readFileSync(require.resolve("world-atlas/land-110m.json"), "utf8"));
const land = feature(topo, topo.objects.land);

const N = 42000;
const golden = Math.PI * (3 - Math.sqrt(5));
const out = [];
for (let i = 0; i < N; i++) {
  const y = 1 - (i / (N - 1)) * 2;
  const theta = golden * i;
  const lat = (Math.asin(y) * 180) / Math.PI;
  const lng = ((((theta * 180) / Math.PI) % 360) + 540) % 360 - 180;
  if (lat < -60) continue; // skip Antarctica, it only adds noise at the pole
  if (geoContains(land, [lng, lat])) out.push(+lat.toFixed(2), +lng.toFixed(2));
}
writeFileSync("public/globe-dots.json", JSON.stringify(out));
console.log(`wrote ${out.length / 2} land dots`);
EOF
node scripts/build-globe-dots.mjs && ls -la public

