@import "tailwindcss";

@theme {
  --color-abyss: #040817;
  --color-navy-950: #060c24;
  --color-navy-900: #0a1030;
  --color-navy-800: #111a45;
  --color-navy-700: #1a2560;
  --color-nx: #1570ff;
  --color-nx-soft: #5b9bff;
  --color-violet: #8b5cf6;
  --color-violet-deep: #5b2ee8;
  --color-aurora: #3be8d0;
  --color-ink: #e8ecff;
  --color-mist: #a3acd1;
  --color-haze: #6e78a3;

  --font-display: var(--font-unbounded), ui-sans-serif, system-ui;
  --font-sans: var(--font-geist), ui-sans-serif, system-ui;
  --font-mono: var(--font-geist-mono), ui-monospace, monospace;

  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);

  --animate-marquee: marquee 48s linear infinite;
  --animate-pulse-ring: pulse-ring 2.4s var(--ease-out-expo) infinite;

  @keyframes marquee {
    to { transform: translateX(-50%); }
  }
  @keyframes pulse-ring {
    0% { transform: scale(0.6); opacity: 0.9; }
    100% { transform: scale(2.4); opacity: 0; }
  }
}

:root {
  color-scheme: dark;
  --line: rgb(148 163 255 / 0.12);
  --line-strong: rgb(148 163 255 / 0.22);
}

html {
  background: var(--color-abyss);
  scroll-behavior: smooth;
  -webkit-text-size-adjust: 100%;
}

body {
  background: var(--color-abyss);
  color: var(--color-ink);
  font-family: var(--font-sans);
  font-feature-settings: "ss01", "cv11";
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overflow-x: clip;
}

::selection {
  background: rgb(139 92 246 / 0.45);
  color: white;
}

:focus-visible {
  outline: 2px solid var(--color-nx-soft);
  outline-offset: 3px;
  border-radius: 6px;
}

/* A panel with a 1px gradient hairline. Used for the few surfaces that carry weight. */
.panel {
  position: relative;
  background:
    linear-gradient(180deg, rgb(17 26 69 / 0.72), rgb(8 13 38 / 0.82)) padding-box,
    linear-gradient(160deg, rgb(120 150 255 / 0.35), rgb(139 92 246 / 0.12) 40%, rgb(148 163 255 / 0.06)) border-box;
  border: 1px solid transparent;
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
}

.hairline {
  border: 1px solid var(--line);
}

.text-balance { text-wrap: balance; }
.text-pretty { text-wrap: pretty; }

/* Headline gradient: runs the full line, never a single accented word. */
.ink-gradient {
  background: linear-gradient(180deg, #ffffff 20%, #b9c3ff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}

.grain::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.06;
  mix-blend-mode: overlay;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='160' height='160'><filter id='n'><feTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='2' stitchTiles='stitch'/></filter><rect width='100%' height='100%' filter='url(%23n)'/></svg>");
}

.mask-fade-x {
  mask-image: linear-gradient(90deg, transparent, black 12%, black 88%, transparent);
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
    scroll-behavior: auto !important;
  }
}

