import type { Metadata, Viewport } from "next";
import { Unbounded, Geist, Geist_Mono } from "next/font/google";
import "./globals.css";

const unbounded = Unbounded({ subsets: ["latin"], variable: "--font-unbounded", weight: ["300", "400", "500", "600"] });
const geist = Geist({ subsets: ["latin"], variable: "--font-geist" });
const geistMono = Geist_Mono({ subsets: ["latin"], variable: "--font-geist-mono" });

export const metadata: Metadata = {
  title: "Nxeon — Cloud VPS and game server hosting",
  description:
    "NVMe cloud servers, one-click game hosting and managed infrastructure across 16 regions. Deploy in under a minute.",
  metadataBase: new URL("https://nxeon.com"),
  openGraph: {
    title: "Nxeon — Cloud VPS and game server hosting",
    description: "Deploy cloud servers and game servers in under a minute, in 16 regions worldwide.",
    type: "website",
  },
};

export const viewport: Viewport = {
  themeColor: "#040817",
  width: "device-width",
  initialScale: 1,
};

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" className={`${unbounded.variable} ${geist.variable} ${geistMono.variable}`}>
      <body>{children}</body>
    </html>
  );
}

