import { useId } from "react";

/** The NX mark, redrawn as vector from the brand artwork. */
export function LogoMark({ className = "h-7 w-auto" }: { className?: string }) {
  const id = useId().replace(/:/g, "");
  return (
    <svg viewBox="185 410 410 202" className={className} aria-hidden="true">
      <defs>
