"use client";

import { useEffect, useRef } from "react";

const VERT = `
attribute vec2 aPos;
void main() { gl_Position = vec4(aPos, 0.0, 1.0); }
`;

// Three curtains of light drifting over a navy sky. The lowest curtain carries the
// teal edge; the upper two stay in the brand blue and violet.
const FRAG = `
precision highp float;
uniform vec2 uRes;
uniform float uTime;
uniform vec2 uMouse;
uniform float uIntensity;

float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
float noise(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { v += a * noise(p); p *= 2.03; a *= 0.5; } return v; }

void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  float aspect = uRes.x / uRes.y;
  float t = uTime * 0.05;
  vec2 m = (uMouse - 0.5) * 0.08;

  vec3 sky = mix(vec3(0.016, 0.031, 0.090), vec3(0.035, 0.050, 0.170), smoothstep(0.1, 1.0, uv.y));
  vec3 col = sky;

  vec3 cBase[3]; vec3 cTop[3];
  cBase[0] = vec3(0.23, 0.91, 0.82); cTop[0] = vec3(0.08, 0.44, 1.00);
  cBase[1] = vec3(0.08, 0.44, 1.00); cTop[1] = vec3(0.36, 0.18, 0.91);
  cBase[2] = vec3(0.55, 0.36, 0.96); cTop[2] = vec3(0.20, 0.10, 0.55);

  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    float x = uv.x * aspect * (0.8 + fi * 0.3) + m.x * (1.0 + fi) + fi * 2.7;
    float wave = sin(x * 1.25 + t * (2.0 + fi) + fi) * 0.09
               + (fbm(vec2(x * 0.7 - t * 0.8, fi * 3.0 + t * 0.3)) - 0.5) * 0.28;
    float center = 0.56 + fi * 0.09 + wave + m.y;
    float d = uv.y - center;
    float edge = smoothstep(-0.05 - fi * 0.01, 0.0, d);
    float fall = exp(-max(d, 0.0) * (5.5 - fi * 1.2));
    float rays = 0.35 + 0.65 * fbm(vec2(x * 11.0 + t * 1.5, uv.y * 0.9 - t * 2.0 + fi));
    float glow = edge * fall * rays;
    vec3 c = mix(cBase[i], cTop[i], clamp(d * 3.0, 0.0, 1.0));
    col += c * glow * (0.55 - fi * 0.1) * uIntensity;
  }

  // sparse stars, dimmed where the aurora is bright
  vec2 sg = floor(gl_FragCoord.xy / 3.0);
  float s = step(0.9975, hash(sg));
  float tw = 0.5 + 0.5 * sin(uTime * 1.3 + hash(sg + 7.0) * 40.0);
  col += s * tw * 0.55 * smoothstep(0.35, 0.9, uv.y) * (1.0 - clamp(length(col - sky) * 2.0, 0.0, 1.0));

  // settle into the page colour at the bottom edge
  col = mix(vec3(0.016, 0.031, 0.090), col, smoothstep(0.0, 0.42, uv.y));
  gl_FragColor = vec4(col, 1.0);
}
`;

type Props = { className?: string; intensity?: number };

export function Aurora({ className = "", intensity = 1 }: Props) {
  const ref = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const gl = canvas.getContext("webgl", { antialias: false, premultipliedAlpha: false, powerPreference: "low-power" });
    if (!gl) return;

    const compile = (type: number, src: string) => {
      const s = gl.createShader(type)!;
      gl.shaderSource(s, src);
      gl.compileShader(s);
      return s;
    };
    const prog = gl.createProgram()!;
    gl.attachShader(prog, compile(gl.VERTEX_SHADER, VERT));
    gl.attachShader(prog, compile(gl.FRAGMENT_SHADER, FRAG));
    gl.linkProgram(prog);
    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) return;
    gl.useProgram(prog);

    const buf = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    const loc = gl.getAttribLocation(prog, "aPos");
    gl.enableVertexAttribArray(loc);
    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);

    const uRes = gl.getUniformLocation(prog, "uRes");
    const uTime = gl.getUniformLocation(prog, "uTime");
    const uMouse = gl.getUniformLocation(prog, "uMouse");
    gl.uniform1f(gl.getUniformLocation(prog, "uIntensity"), intensity);

    // The aurora is soft by nature, so render at reduced resolution and let CSS scale it.
    const scale = 0.5;
    const resize = () => {
      const w = Math.max(1, Math.floor(canvas.clientWidth * scale));
      const h = Math.max(1, Math.floor(canvas.clientHeight * scale));
      canvas.width = w;
      canvas.height = h;
      gl.viewport(0, 0, w, h);
      gl.uniform2f(uRes, w, h);
    };
    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(canvas);

    const mouse = { x: 0.5, y: 0.5, tx: 0.5, ty: 0.5 };
    const onMove = (e: PointerEvent) => {
      mouse.tx = e.clientX / window.innerWidth;
      mouse.ty = 1 - e.clientY / window.innerHeight;
    };
    window.addEventListener("pointermove", onMove, { passive: true });

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let visible = true;
    const io = new IntersectionObserver(([entry]) => (visible = entry.isIntersecting));
    io.observe(canvas);

    let raf = 0;
    const start = performance.now();
    const frame = (now: number) => {
      raf = requestAnimationFrame(frame);
      if (!visible) return;
      mouse.x += (mouse.tx - mouse.x) * 0.03;
      mouse.y += (mouse.ty - mouse.y) * 0.03;
      gl.uniform1f(uTime, reduced ? 12 : (now - start) / 1000);
      gl.uniform2f(uMouse, mouse.x, mouse.y);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      if (reduced) cancelAnimationFrame(raf);
    };
    raf = requestAnimationFrame(frame);

    return () => {
      cancelAnimationFrame(raf);
      ro.disconnect();
      io.disconnect();
      window.removeEventListener("pointermove", onMove);
      gl.getExtension("WEBGL_lose_context")?.loseContext();
    };
  }, [intensity]);

  return (
    <div className={`pointer-events-none absolute inset-0 ${className}`} aria-hidden="true">
      {/* CSS fallback, visible until (or if) WebGL paints */}
      <div className="absolute inset-0 bg-[radial-gradient(80%_60%_at_30%_20%,rgb(21_112_255/0.25),transparent_60%),radial-gradient(60%_50%_at_75%_10%,rgb(139_92_246/0.28),transparent_60%)]" />
      <canvas ref={ref} className="absolute inset-0 h-full w-full" />
    </div>
  );
}

