  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
}
float fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { v += a * noise(p); p *= 2.03; a *= 0.5; } return v; }

void main() {
  vec2 uv = gl_FragCoord.xy / uRes;
  float aspect = uRes.x / uRes.y;
  float t = uTime * 0.05;
  vec2 m = (uMouse - 0.5) * 0.08;

  vec3 sky = mix(vec3(0.016, 0.031, 0.090), vec3(0.035, 0.050, 0.170), smoothstep(0.1, 1.0, uv.y));
  vec3 col = sky;

  vec3 cBase[3]; vec3 cTop[3];
  cBase[0] = vec3(0.23, 0.91, 0.82); cTop[0] = vec3(0.08, 0.44, 1.00);
  cBase[1] = vec3(0.08, 0.44, 1.00); cTop[1] = vec3(0.36, 0.18, 0.91);
  cBase[2] = vec3(0.55, 0.36, 0.96); cTop[2] = vec3(0.20, 0.10, 0.55);

  for (int i = 0; i < 3; i++) {
