"use client";

import { useEffect, useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { Menu, X, Server, Gamepad2, Building2 } from "lucide-react";
import { Logo } from "./brand/Logo";

const PRODUCTS = [
  { icon: Server, title: "Cloud VPS", body: "NVMe servers with root access, from $4 a month", href: "#products" },
  { icon: Gamepad2, title: "Game servers", body: "One-click Minecraft, Rust, Palworld and 60 more", href: "#products" },
  { icon: Building2, title: "Managed & dedicated", body: "Bare metal and a team that watches it for you", href: "#products" },
];

const LINKS = [
  { label: "Locations", href: "#network" },
  { label: "Pricing", href: "#pricing" },
  { label: "Developers", href: "#developers" },
  { label: "Docs", href: "#" },
];

export function Nav() {
  const [scrolled, setScrolled] = useState(false);
  const [open, setOpen] = useState(false);
  const [productsOpen, setProductsOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 12);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  useEffect(() => {
    document.body.style.overflow = open ? "hidden" : "";
  }, [open]);

  return (
    <header className="fixed inset-x-0 top-0 z-50 px-4 pt-3 sm:px-6">
      <nav
        aria-label="Main"
        className={`mx-auto flex h-14 max-w-6xl items-center justify-between rounded-2xl px-3 pl-4 transition-[background,border-color,box-shadow] duration-300 ${
          scrolled
            ? "border border-[var(--line)] bg-navy-950/70 shadow-[0_10px_40px_-12px_rgb(0_0_0/0.6)] backdrop-blur-xl"
            : "border border-transparent"
        }`}
      >
        <a href="#top" className="rounded-lg" aria-label="Nxeon home">
          <Logo />
        </a>

        <ul className="hidden items-center gap-1 text-sm text-mist md:flex">
          <li className="relative" onMouseEnter={() => setProductsOpen(true)} onMouseLeave={() => setProductsOpen(false)}>
            <button
              type="button"
              className="cursor-pointer rounded-lg px-3 py-2 transition-colors hover:text-ink"
              aria-expanded={productsOpen}
              onClick={() => setProductsOpen((v) => !v)}
            >
              Products
            </button>
            <AnimatePresence>
              {productsOpen && (
                <motion.div
                  initial={{ opacity: 0, y: 6, scale: 0.98 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={{ opacity: 0, y: 4, scale: 0.98 }}
                  transition={{ duration: 0.18, ease: [0.16, 1, 0.3, 1] }}
                  className="absolute left-1/2 top-full w-[360px] -translate-x-1/2 pt-2"
                >
                  <div className="panel rounded-2xl p-2 shadow-2xl">
                    {PRODUCTS.map(({ icon: Icon, title, body, href }) => (
                      <a
                        key={title}
                        href={href}
                        className="flex gap-3 rounded-xl p-3 transition-colors hover:bg-white/[0.04]"
                        onClick={() => setProductsOpen(false)}
                      >
                        <span className="mt-0.5 grid size-9 shrink-0 place-items-center rounded-lg bg-nx/15 text-nx-soft">
                          <Icon className="size-[18px]" />
                        </span>
                        <span>
                          <span className="block text-sm font-medium text-ink">{title}</span>
                          <span className="block text-[13px] leading-snug text-haze">{body}</span>
                        </span>
                      </a>
                    ))}
                  </div>
                </motion.div>
              )}
            </AnimatePresence>
          </li>
          {LINKS.map((l) => (
            <li key={l.label}>
              <a href={l.href} className="rounded-lg px-3 py-2 transition-colors hover:text-ink">
                {l.label}
              </a>
            </li>
          ))}
        </ul>

        <div className="hidden items-center gap-2 md:flex">
          <a href="#" className="rounded-lg px-3 py-2 text-sm text-mist transition-colors hover:text-ink">
            Sign in
          </a>
          <a
            href="#pricing"
            className="rounded-xl bg-ink px-4 py-2 text-sm font-medium text-abyss transition-[transform,background] duration-200 hover:bg-white active:scale-[0.97]"
          >
            Deploy a server
          </a>
        </div>

        <button
          type="button"
          className="grid size-11 cursor-pointer place-items-center rounded-xl text-ink md:hidden"
          aria-label={open ? "Close menu" : "Open menu"}
          aria-expanded={open}
          onClick={() => setOpen((v) => !v)}
        >
          {open ? <X className="size-5" /> : <Menu className="size-5" />}
        </button>
      </nav>

      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0, y: -8 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -8 }}
            transition={{ duration: 0.2 }}
            className="panel mx-auto mt-2 max-w-6xl rounded-2xl p-3 md:hidden"
          >
            {PRODUCTS.map(({ icon: Icon, title, href }) => (
              <a key={title} href={href} onClick={() => setOpen(false)} className="flex items-center gap-3 rounded-xl p-3 text-ink">
                <Icon className="size-[18px] text-nx-soft" /> {title}
              </a>
            ))}
            <div className="my-2 h-px bg-[var(--line)]" />
            {LINKS.map((l) => (
              <a key={l.label} href={l.href} onClick={() => setOpen(false)} className="block rounded-xl p-3 text-mist">
                {l.label}
              </a>
            ))}
            <a href="#pricing" onClick={() => setOpen(false)} className="mt-2 block rounded-xl bg-ink p-3 text-center font-medium text-abyss">
              Deploy a server
            </a>
          </motion.div>
        )}
      </AnimatePresence>
    </header>
  );
}

