"use client";

import { useEffect, useMemo, useState } from "react";
import { motion } from "motion/react";
import { Check, Copy, ShieldCheck, Users, Activity, DatabaseBackup, Headset } from "lucide-react";

/* ------------------------------------------------------------------ */
/* Developers: a deploy playing out in a terminal                      */
/* ------------------------------------------------------------------ */

const DEPLOY: { text: string; kind: "cmd" | "ok" | "done"; delay: number }[] = [
  { text: "nx servers create --plan vps-4 --region fra1 --image ubuntu-24.04", kind: "cmd", delay: 300 },
  { text: "Reserved 4 vCPU, 8 GB RAM, 160 GB NVMe in Frankfurt", kind: "ok", delay: 1500 },
  { text: "Wrote image ubuntu-24.04 LTS", kind: "ok", delay: 900 },
  { text: "Installed SSH key “laptop”", kind: "ok", delay: 600 },
  { text: "Opened ports 22, 80, 443", kind: "ok", delay: 600 },
  { text: "Ready in 38s", kind: "done", delay: 900 },
];

export function DevConsole() {
  const [shown, setShown] = useState(0);
  const [typed, setTyped] = useState(0);
  const cmd = DEPLOY[0].text;

  useEffect(() => {
    if (typed < cmd.length) {
      const id = setTimeout(() => setTyped((t) => t + 1), typed === 0 ? 500 : 22);
      return () => clearTimeout(id);
    }
    if (shown < DEPLOY.length) {
      const id = setTimeout(() => setShown((s) => s + 1), DEPLOY[shown]?.delay ?? 600);
      return () => clearTimeout(id);
    }
  }, [typed, shown, cmd.length]);

  return (
    <div className="font-mono text-[12.5px] leading-6 sm:text-[13px]">
      <div className="flex items-center gap-2 border-b border-[var(--line)] px-4 py-3">
        <span className="size-2.5 rounded-full bg-white/15" />
        <span className="size-2.5 rounded-full bg-white/15" />
        <span className="size-2.5 rounded-full bg-white/15" />
        <span className="ml-2 text-xs text-haze">~/api — zsh</span>
      </div>
      <div className="min-h-[268px] space-y-1 p-4 sm:p-5">
        <p className="break-words text-ink">
          <span className="select-none text-violet">❯ </span>
          {cmd.slice(0, typed)}
          {typed < cmd.length && <Caret />}
        </p>
        {DEPLOY.slice(1, shown).map((l) =>
          l.kind === "done" ? (
            <motion.div key={l.text} initial={{ opacity: 0, y: 4 }} animate={{ opacity: 1, y: 0 }} className="pt-3">
              <p className="text-aurora">{l.text}</p>
              <p className="text-mist">
                ssh root@<span className="text-ink">203.0.113.42</span>
              </p>
              <p className="pt-2 text-ink">
                <span className="select-none text-violet">❯ </span>
                <Caret />
              </p>
            </motion.div>
          ) : (
            <motion.p key={l.text} initial={{ opacity: 0, x: -4 }} animate={{ opacity: 1, x: 0 }} className="flex gap-2 text-mist">
              <Check className="mt-[5px] size-3.5 shrink-0 text-nx-soft" />
              {l.text}
            </motion.p>
          ),
        )}
      </div>
    </div>
  );
}

function Caret() {
  return <span className="ml-px inline-block h-4 w-[7px] translate-y-[3px] animate-pulse bg-ink/80" />;
}

/* ------------------------------------------------------------------ */
/* Gamers: a live server card                                          */
/* ------------------------------------------------------------------ */

function usePlayerSeries(length = 32) {
  const [series, setSeries] = useState<number[]>(() =>
    Array.from({ length }, (_, i) => 16 + Math.round(6 * Math.sin(i / 4) + (i % 3))),
  );
  useEffect(() => {
    const id = setInterval(() => {
      setSeries((s) => {
        const last = s[s.length - 1];
        const next = Math.max(8, Math.min(40, last + Math.round((Math.random() - 0.45) * 4)));
        return [...s.slice(1), next];
      });
    }, 1400);
    return () => clearInterval(id);
  }, []);
  return series;
}

export function GameConsole() {
  const series = usePlayerSeries();
  const players = series[series.length - 1];
  const [copied, setCopied] = useState(false);

  const path = useMemo(() => {
    const w = 100, h = 36, max = 40;
    return series.map((v, i) => `${i === 0 ? "M" : "L"}${(i / (series.length - 1)) * w},${h - (v / max) * h}`).join(" ");
  }, [series]);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText("smp.nxeon.gg");
    } catch {}
    setCopied(true);
    setTimeout(() => setCopied(false), 1600);
  };

  return (
    <div className="p-4 sm:p-5">
      <div className="flex items-start justify-between gap-4">
        <div className="flex items-center gap-3">
          <div className="grid size-11 place-items-center rounded-xl bg-[linear-gradient(135deg,#2f9e4f,#1d6b34)] font-display text-sm text-white shadow-inner">
            SMP
          </div>
          <div>
            <p className="font-medium text-ink">Nightfall Survival</p>
            <p className="text-[13px] text-haze">Minecraft Java 1.21 · Paper</p>
          </div>
        </div>
        <span className="inline-flex items-center gap-1.5 rounded-full bg-aurora/10 px-2.5 py-1 text-xs text-aurora">
          <span className="relative flex size-1.5">
            <span className="absolute inline-flex size-full animate-ping rounded-full bg-aurora opacity-60" />
            <span className="relative inline-flex size-1.5 rounded-full bg-aurora" />
          </span>
          Online
        </span>
      </div>

      <div className="mt-5 rounded-xl border border-[var(--line)] bg-abyss/40 p-4">
        <div className="flex items-baseline justify-between">
          <p className="flex items-center gap-2 text-sm text-mist">
            <Users className="size-4" /> Players
          </p>
          <p className="font-display text-lg tabular-nums text-ink">
            {players}
            <span className="text-sm text-haze">/40</span>
          </p>
        </div>
        <svg viewBox="0 0 100 36" preserveAspectRatio="none" className="mt-3 h-16 w-full" aria-hidden="true">
          <defs>
            <linearGradient id="pl-fill" x1="0" x2="0" y1="0" y2="1">
              <stop offset="0" stopColor="#8b5cf6" stopOpacity="0.45" />
              <stop offset="1" stopColor="#8b5cf6" stopOpacity="0" />
            </linearGradient>
          </defs>
          <path d={`${path} L100,36 L0,36 Z`} fill="url(#pl-fill)" />
          <path d={path} fill="none" stroke="#a78bfa" strokeWidth="1.2" vectorEffect="non-scaling-stroke" />
        </svg>
      </div>

      <dl className="mt-3 grid grid-cols-3 gap-3 text-sm">
        {[
          ["TPS", "20.0"],
          ["Ping", "18 ms"],
          ["Region", "London"],
        ].map(([k, v]) => (
          <div key={k} className="rounded-xl border border-[var(--line)] px-3 py-2.5">
            <dt className="text-xs text-haze">{k}</dt>
            <dd className="mt-0.5 tabular-nums text-ink">{v}</dd>
          </div>
        ))}
      </dl>

      <button
        type="button"
        onClick={copy}
        className="mt-3 flex w-full cursor-pointer items-center justify-between rounded-xl border border-[var(--line)] bg-white/[0.02] px-4 py-3 text-left transition-colors hover:bg-white/[0.05]"
      >
        <span>
          <span className="block text-xs text-haze">Join address</span>
          <span className="font-mono text-sm text-ink">smp.nxeon.gg</span>
        </span>
        <span className="flex items-center gap-1.5 text-xs text-mist">
          {copied ? <Check className="size-4 text-aurora" /> : <Copy className="size-4" />}
          {copied ? "Copied" : "Copy"}
        </span>
      </button>
    </div>
  );
}

/* ------------------------------------------------------------------ */
/* Business: uptime and the things that keep it there                  */
/* ------------------------------------------------------------------ */

const DAYS = Array.from({ length: 60 }, (_, i) => (i === 41 ? "degraded" : "up"));

export function BusinessConsole() {
  return (
    <div className="p-4 sm:p-5">
      <div className="flex items-baseline justify-between">
        <p className="flex items-center gap-2 text-sm text-mist">
          <Activity className="size-4" /> Uptime, last 60 days
        </p>
        <p className="font-display text-2xl tabular-nums text-ink">99.99%</p>
      </div>
      <div className="mt-4 flex h-10 items-end gap-[3px]" role="img" aria-label="59 days fully up, one day briefly degraded">
        {DAYS.map((d, i) => (
          <motion.span
            key={i}
            initial={{ scaleY: 0 }}
            animate={{ scaleY: 1 }}
            transition={{ delay: i * 0.012, duration: 0.4, ease: [0.16, 1, 0.3, 1] }}
            style={{ transformOrigin: "bottom" }}
            className={`h-full flex-1 rounded-[2px] ${d === "up" ? "bg-nx/70" : "bg-amber-400/80"}`}
            title={d === "up" ? "Operational" : "Degraded for 4 minutes"}
          />
        ))}
      </div>
      <p className="mt-2 text-xs text-haze">One 4-minute slowdown during a planned network upgrade.</p>

      <ul className="mt-5 space-y-2">
        {[
          { icon: ShieldCheck, title: "DDoS protection", body: "3 attacks absorbed this week, none reached you" },
          { icon: DatabaseBackup, title: "Nightly backups", body: "14 restore points kept, last one at 03:00" },
          { icon: Headset, title: "Human support", body: "Median first reply in 4 minutes, all day" },
        ].map(({ icon: Icon, title, body }, i) => (
          <motion.li
            key={title}
            initial={{ opacity: 0, y: 6 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.35 + i * 0.08 }}
            className="flex items-center gap-3 rounded-xl border border-[var(--line)] px-3.5 py-3"
          >
            <span className="grid size-9 shrink-0 place-items-center rounded-lg bg-violet/15 text-violet">
              <Icon className="size-[18px]" />
            </span>
            <span>
              <span className="block text-sm text-ink">{title}</span>
              <span className="block text-[13px] text-haze">{body}</span>
            </span>
          </motion.li>
        ))}
      </ul>
    </div>
  );
}

