"use client";

import { useEffect, useMemo, useState } from "react";
import { motion } from "motion/react";
import { Check, Copy, ShieldCheck, Users, Activity, DatabaseBackup, Headset } from "lucide-react";

/* ------------------------------------------------------------------ */
/* Developers: a deploy playing out in a terminal                      */
/* ------------------------------------------------------------------ */

const DEPLOY: { text: string; kind: "cmd" | "ok" | "done"; delay: number }[] = [
  { text: "nx servers create --plan vps-4 --region fra1 --image ubuntu-24.04", kind: "cmd", delay: 300 },
  { text: "Reserved 4 vCPU, 8 GB RAM, 160 GB NVMe in Frankfurt", kind: "ok", delay: 1500 },
  { text: "Wrote image ubuntu-24.04 LTS", kind: "ok", delay: 900 },
  { text: "Installed SSH key “laptop”", kind: "ok", delay: 600 },
  { text: "Opened ports 22, 80, 443", kind: "ok", delay: 600 },
  { text: "Ready in 38s", kind: "done", delay: 900 },
];

export function DevConsole() {
  const [shown, setShown] = useState(0);
  const [typed, setTyped] = useState(0);
  const cmd = DEPLOY[0].text;

  useEffect(() => {
    if (typed < cmd.length) {
      const id = setTimeout(() => setTyped((t) => t + 1), typed === 0 ? 500 : 22);
      return () => clearTimeout(id);
    }
    if (shown < DEPLOY.length) {
      const id = setTimeout(() => setShown((s) => s + 1), DEPLOY[shown]?.delay ?? 600);
      return () => clearTimeout(id);
    }
  }, [typed, shown, cmd.length]);

  return (
    <div className="font-mono text-[12.5px] leading-6 sm:text-[13px]">
      <div className="flex items-center gap-2 border-b border-[var(--line)] px-4 py-3">
        <span className="size-2.5 rounded-full bg-white/15" />
        <span className="size-2.5 rounded-full bg-white/15" />
        <span className="size-2.5 rounded-full bg-white/15" />
        <span className="ml-2 text-xs text-haze">~/api — zsh</span>
      </div>
      <div className="min-h-[268px] space-y-1 p-4 sm:p-5">
        <p className="break-words text-ink">
          <span className="select-none text-violet">❯ </span>
          {cmd.slice(0, typed)}
          {typed < cmd.length && <Caret />}
        </p>
        {DEPLOY.slice(1, shown).map((l) =>
          l.kind === "done" ? (
            <motion.div key={l.text} initial={{ opacity: 0, y: 4 }} animate={{ opacity: 1, y: 0 }} className="pt-3">
              <p className="text-aurora">{l.text}</p>
              <p className="text-mist">
                ssh root@<span className="text-ink">203.0.113.42</span>
              </p>
              <p className="pt-2 text-ink">
                <span className="select-none text-violet">❯ </span>
                <Caret />
              </p>
            </motion.div>
          ) : (
            <motion.p key={l.text} initial={{ opacity: 0, x: -4 }} animate={{ opacity: 1, x: 0 }} className="flex gap-2 text-mist">
              <Check className="mt-[5px] size-3.5 shrink-0 text-nx-soft" />
              {l.text}
            </motion.p>
          ),
        )}
      </div>
    </div>
  );
}

function Caret() {
  return <span className="ml-px inline-block h-4 w-[7px] translate-y-[3px] animate-pulse bg-ink/80" />;
}

/* ------------------------------------------------------------------ */
/* Gamers: a live server card                                          */
/* ------------------------------------------------------------------ */

function usePlayerSeries(length = 32) {
  const [series, setSeries] = useState<number[]>(() =>
    Array.from({ length }, (_, i) => 16 + Math.round(6 * Math.sin(i / 4) + (i % 3))),
  );
  useEffect(() => {
    const id = setInterval(() => {
      setSeries((s) => {
        const last = s[s.length - 1];
        const next = Math.max(8, Math.min(40, last + Math.round((Math.random() - 0.45) * 4)));
        return [...s.slice(1), next];
      });
    }, 1400);
    return () => clearInterval(id);
  }, []);
  return series;
}

export function GameConsole() {
  const series = usePlayerSeries();
  const players = series[series.length - 1];
  const [copied, setCopied] = useState(false);

  const path = useMemo(() => {
    const w = 100, h = 36, max = 40;
    return series.map((v, i) => `${i === 0 ? "M" : "L"}${(i / (series.length - 1)) * w},${h - (v / max) * h}`).join(" ");
  }, [series]);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText("smp.nxeon.gg");
