            <p className="text-[13px] text-haze">Minecraft Java 1.21 · Paper</p>
          </div>
        </div>
        <span className="inline-flex items-center gap-1.5 rounded-full bg-aurora/10 px-2.5 py-1 text-xs text-aurora">
          <span className="relative flex size-1.5">
            <span className="absolute inline-flex size-full animate-ping rounded-full bg-aurora opacity-60" />
            <span className="relative inline-flex size-1.5 rounded-full bg-aurora" />
          </span>
          Online
        </span>
      </div>

      <div className="mt-5 rounded-xl border border-[var(--line)] bg-abyss/40 p-4">
        <div className="flex items-baseline justify-between">
          <p className="flex items-center gap-2 text-sm text-mist">
