          <path d={path} fill="none" stroke="#a78bfa" strokeWidth="1.2" vectorEffect="non-scaling-stroke" />
        </svg>
      </div>

      <dl className="mt-3 grid grid-cols-3 gap-3 text-sm">
        {[
          ["TPS", "20.0"],
