"use client";

import { useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { Aurora } from "../effects/Aurora";
import { DevConsole, GameConsole, BusinessConsole } from "./consoles";
import { ONLINE_COUNT } from "@/lib/datacenters";

const AUDIENCES = [
  {
    id: "build",
    label: "Build",
    who: "Developers",
    body: "NVMe cloud servers with full root, a real API and a CLI that stays out of your way. Spin one up from the terminal before the coffee is ready.",
    Console: DevConsole,
  },
  {
    id: "play",
    label: "Play",
    who: "Gamers",
    body: "One-click Minecraft, Rust, Palworld, CS2 and 60 more. Mods install from a list, backups run themselves and your friends connect with low ping.",
    Console: GameConsole,
  },
  {
    id: "run",
    label: "Run",
    who: "Businesses",
    body: "Managed servers with DDoS protection, nightly backups and people who answer in minutes. You run the company, we keep the machines up.",
    Console: BusinessConsole,
  },
] as const;

export function Hero() {
  const [active, setActive] = useState(0);
  const a = AUDIENCES[active];

  return (
    <section id="top" className="relative isolate overflow-hidden pb-16 pt-32 sm:pt-40 lg:pb-28">
      <Aurora className="-z-10" />
      <div className="grain pointer-events-none absolute inset-0 -z-10" />

      <div className="mx-auto grid max-w-6xl items-center gap-12 px-4 sm:px-6 lg:grid-cols-[1.08fr_1fr] lg:gap-16">
        <div>
          <motion.a
            href="#network"
            initial={{ opacity: 0, y: 8 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, ease: [0.16, 1, 0.3, 1] }}
            className="inline-flex items-center gap-2 rounded-full border border-[var(--line-strong)] bg-navy-900/50 py-1.5 pl-2 pr-3.5 text-[13px] text-mist backdrop-blur transition-colors hover:text-ink"
          >
            <span className="rounded-full bg-aurora/15 px-2 py-0.5 text-xs text-aurora">New</span>
            Game servers now live in Tokyo and Mumbai
          </motion.a>

          <motion.h1
            initial={{ opacity: 0, y: 16 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.9, delay: 0.08, ease: [0.16, 1, 0.3, 1] }}
            className="ink-gradient text-balance mt-7 font-display text-[clamp(2.4rem,6vw,4.6rem)] font-normal leading-[1.02] tracking-[-0.035em]"
          >
            Servers for what you build, play and run.
          </motion.h1>

          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ duration: 0.8, delay: 0.3 }}
            className="mt-9"
          >
            <div
              role="tablist"
              aria-label="Choose what you need a server for"
              className="relative inline-grid grid-cols-3 rounded-2xl border border-[var(--line-strong)] bg-navy-950/60 p-1 backdrop-blur"
            >
              {AUDIENCES.map((x, i) => (
                <button
                  key={x.id}
                  role="tab"
                  id={`tab-${x.id}`}
                  aria-selected={i === active}
                  aria-controls="hero-panel"
                  onClick={() => setActive(i)}
                  className={`relative z-10 cursor-pointer rounded-xl px-4 py-2.5 text-left transition-colors sm:px-5 ${
                    i === active ? "text-ink" : "text-haze hover:text-mist"
                  }`}
                >
                  {i === active && (
                    <motion.span
                      layoutId="aud-pill"
                      className="absolute inset-0 -z-10 rounded-xl bg-[linear-gradient(135deg,rgb(21_112_255/0.35),rgb(139_92_246/0.35))] shadow-[inset_0_1px_0_rgb(255_255_255/0.12)]"
                      transition={{ type: "spring", stiffness: 420, damping: 36 }}
                    />
                  )}
                  <span className="block font-display text-sm">{x.label}</span>
                  <span className="block text-xs opacity-80">{x.who}</span>
                </button>
              ))}
            </div>

            <div className="relative mt-6 min-h-[96px] max-w-[34rem]">
              <AnimatePresence mode="wait">
                <motion.p
                  key={a.id}
                  initial={{ opacity: 0, y: 6 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -6 }}
                  transition={{ duration: 0.25 }}
                  className="text-pretty text-[17px] leading-relaxed text-mist"
                >
                  {a.body}
                </motion.p>
              </AnimatePresence>
            </div>

            <div className="mt-6 flex flex-wrap items-center gap-3">
              <a
                href="#pricing"
                className="group relative inline-flex h-12 items-center rounded-xl bg-[linear-gradient(135deg,#1570ff,#6d3cf0)] px-6 font-medium text-white shadow-[0_8px_30px_-8px_rgb(91_46_232/0.8),inset_0_1px_0_rgb(255_255_255/0.2)] transition-transform duration-200 hover:-translate-y-px active:scale-[0.98]"
              >
                Deploy a server
              </a>
              <a
                href="#pricing"
                className="inline-flex h-12 items-center rounded-xl border border-[var(--line-strong)] px-6 text-ink transition-colors hover:bg-white/[0.04]"
              >
                See pricing
              </a>
              <p className="w-full pt-1 text-[13px] text-haze sm:w-auto sm:pl-2 sm:pt-0">
                From $4/month, billed hourly, {ONLINE_COUNT} regions
              </p>
            </div>
          </motion.div>
        </div>

        <motion.div
          initial={{ opacity: 0, y: 24, rotateX: 8 }}
          animate={{ opacity: 1, y: 0, rotateX: 0 }}
          transition={{ duration: 1.1, delay: 0.2, ease: [0.16, 1, 0.3, 1] }}
          style={{ perspective: 1200 }}
          className="relative"
        >
          <div className="absolute -inset-8 -z-10 rounded-[40px] bg-[radial-gradient(closest-side,rgb(91_46_232/0.35),transparent)] blur-2xl" />
          <div
            id="hero-panel"
            role="tabpanel"
            aria-labelledby={`tab-${a.id}`}
            className="panel overflow-hidden rounded-[26px] shadow-[0_40px_120px_-30px_rgb(0_0_0/0.9)]"
          >
            <AnimatePresence mode="wait">
              <motion.div
                key={a.id}
                initial={{ opacity: 0, filter: "blur(6px)" }}
                animate={{ opacity: 1, filter: "blur(0px)" }}
                exit={{ opacity: 0, filter: "blur(6px)" }}
                transition={{ duration: 0.3 }}
                className="min-h-[360px]"
              >
                <a.Console />
              </motion.div>
            </AnimatePresence>
          </div>
        </motion.div>
      </div>
    </section>
  );
}

