import {
  siUbuntu, siDebian, siRockylinux, siAlmalinux, siDocker, siKubernetes, siTerraform, siAnsible,
  siGithub, siGitlab, siCloudflare, siWordpress, siCpanel, siPlesk, siPterodactyl, siTailscale,
  siGrafana, siSteam, siCounterstrike, siDiscord, siUnrealengine, siNodedotjs, siPostgresql, siLaravel,
  type SimpleIcon,
} from "simple-icons";

const STACK: SimpleIcon[] = [
  siUbuntu, siDebian, siDocker, siKubernetes, siTerraform, siGithub, siCloudflare, siWordpress,
  siRockylinux, siAlmalinux, siAnsible, siGitlab, siCpanel, siPlesk, siTailscale, siGrafana,
  siNodedotjs, siPostgresql, siLaravel,
];

const GAMES: (string | SimpleIcon)[] = [
  "Minecraft", siCounterstrike, "Rust", "Palworld", "Valheim", siSteam, "ARK", "Terraria",
  "Satisfactory", siPterodactyl, "Enshrouded", "Project Zomboid", siDiscord, "7 Days to Die", "FiveM", siUnrealengine,
];

function Icon({ icon }: { icon: SimpleIcon }) {
  return (
    <li
      className="group flex shrink-0 items-center gap-2.5 px-6 text-haze transition-colors duration-300 hover:text-[var(--brand)]"
      style={{ ["--brand" as string]: `#${icon.hex === "000000" || icon.hex === "181717" ? "e8ecff" : icon.hex}` }}
    >
      <svg viewBox="0 0 24 24" className="size-5 fill-current" aria-hidden="true">
        <path d={icon.path} />
      </svg>
      <span className="text-[15px] text-mist/80 transition-colors group-hover:text-ink">{icon.title}</span>
    </li>
  );
}

function Row({ items, reverse = false }: { items: (string | SimpleIcon)[]; reverse?: boolean }) {
  const doubled = [...items, ...items];
  return (
    <div className="mask-fade-x group/row overflow-hidden">
      <ul
        className={`flex w-max animate-marquee py-3 group-hover/row:[animation-play-state:paused] ${
          reverse ? "[animation-direction:reverse]" : ""
        }`}
      >
        {doubled.map((it, i) =>
          typeof it === "string" ? (
            <li key={i} aria-hidden={i >= items.length} className="flex shrink-0 items-center px-6 font-display text-[14px] text-mist/70 transition-colors hover:text-ink">
              {it}
            </li>
          ) : (
            <Icon key={i} icon={it} />
          ),
        )}
      </ul>
    </div>
  );
}

export function LogoCloud() {
  return (
    <section aria-labelledby="proof-title" className="relative py-14">
      <div className="mx-auto max-w-6xl px-4 sm:px-6">
        <h2 id="proof-title" className="text-center text-[15px] text-mist">
          48,000 developers, studios and game communities run on Nxeon, with the tools they already use
        </h2>
      </div>
      <div className="mt-8 space-y-2">
        <Row items={STACK} />
        <Row items={GAMES} reverse />
      </div>
    </section>
  );
}

