/* Tiny isometric toolkit for the product illustrations. */

export const TW = 22; // half tile width
export const TH = 12.7; // half tile height
export const ZH = 25; // unit height

export function p(x: number, y: number, z: number): [number, number] {
  return [(x - y) * TW, (x + y) * TH - z * ZH];
}

const pts = (a: [number, number][]) => a.map(([x, y]) => `${x.toFixed(2)},${y.toFixed(2)}`).join(" ");

type BoxProps = {
  x: number; y: number; z: number;
  dx?: number; dy?: number; dz?: number;
  top: string; left: string; right: string;
  stroke?: string;
};

export function Box({ x, y, z, dx = 1, dy = 1, dz = 1, top, left, right, stroke = "rgb(160 180 255 / 0.18)" }: BoxProps) {
  return (
    <g stroke={stroke} strokeWidth={0.6} strokeLinejoin="round">
      <polygon points={pts([p(x, y + dy, z), p(x + dx, y + dy, z), p(x + dx, y + dy, z + dz), p(x, y + dy, z + dz)])} fill={left} />
      <polygon points={pts([p(x + dx, y, z), p(x + dx, y + dy, z), p(x + dx, y + dy, z + dz), p(x + dx, y, z + dz)])} fill={right} />
      <polygon points={pts([p(x, y, z + dz), p(x + dx, y, z + dz), p(x + dx, y + dy, z + dz), p(x, y + dy, z + dz)])} fill={top} />
    </g>
  );
}

/** A stack of server blades with blinking status lights. */
export function RackIllustration({ className = "" }: { className?: string }) {
  const blades = [0, 1, 2, 3, 4];
  return (
    <svg viewBox="-150 -170 300 290" className={className} aria-hidden="true">
      <defs>
        <linearGradient id="rk-top" x1="0" x2="1" y1="0" y2="1">
          <stop offset="0" stopColor="#2a3a8f" />
          <stop offset="1" stopColor="#1a2466" />
        </linearGradient>
        <radialGradient id="rk-floor">
          <stop offset="0" stopColor="#5b2ee8" stopOpacity="0.55" />
          <stop offset="1" stopColor="#5b2ee8" stopOpacity="0" />
        </radialGradient>
      </defs>
      <ellipse cx={p(2.5, 1.5, 0)[0]} cy={p(2.5, 1.5, 0)[1] + 8} rx="150" ry="60" fill="url(#rk-floor)" />
      {blades.map((i) => {
        const z = i * 0.62;
        return (
          <g key={i}>
            <Box x={0} y={0} z={z} dx={5} dy={3} dz={0.5} top="url(#rk-top)" left="#121a4d" right="#0d1440" />
            {Array.from({ length: 6 }, (_, j) => {
              const [lx, ly] = p(0.45 + j * 0.32, 3, z + 0.25);
              return (
                <circle
                  key={j}
                  cx={lx}
                  cy={ly}
                  r={1.8}
                  className="led"
                  fill={j === 0 ? "#3be8d0" : j % 2 ? "#5b9bff" : "#8b5cf6"}
                  style={{ animationDelay: `${(i * 0.37 + j * 0.53) % 2.4}s` }}
                />
              );
            })}
            {Array.from({ length: 7 }, (_, j) => {
              const [a1, b1] = p(2.6 + j * 0.3, 3, z + 0.12);
              const [a2, b2] = p(2.6 + j * 0.3, 3, z + 0.38);
              return <line key={j} x1={a1} y1={b1} x2={a2} y2={b2} stroke="rgb(160 180 255 / 0.25)" strokeWidth="1" />;
            })}
          </g>
        );
      })}
    </svg>
  );
}

const HEIGHTS = [
  [1, 1, 2, 2, 1, 0],
  [1, 2, 3, 2, 1, 0],
  [2, 3, 4, 3, 2, 1],
  [1, 2, 3, 3, 2, 1],
  [0, 1, 2, 2, 1, 0],
  [0, 0, 1, 1, 0, 0],
];

/** A little voxel island, lit from inside. */
export function VoxelIllustration({ className = "" }: { className?: string }) {
  const cells: { x: number; y: number; z: number }[] = [];
  HEIGHTS.forEach((row, y) => row.forEach((h, x) => { for (let z = 0; z < Math.max(1, h); z++) cells.push({ x, y, z }); }));
  cells.sort((a, b) => a.x + a.y + a.z - (b.x + b.y + b.z) || a.z - b.z);
  const topFor = (z: number, h: number) =>
