void main() {
  vec2 c = gl_PointCoord - 0.5;
  float d = length(c);
  if (d > 0.5) discard;
  float soft = smoothstep(0.5, 0.2, d);
  vec3 blue = vec3(0.33, 0.52, 1.0);
  vec3 violet = vec3(0.62, 0.45, 1.0);
  vec3 col = mix(blue, violet, smoothstep(-0.2, 0.9, vLat));
  col = mix(col, vec3(0.75, 0.95, 1.0), vFocus * 0.8);
  float a = smoothstep(-0.05, 0.55, vFacing) * (0.55 + vFocus * 0.45) * soft;
  gl_FragColor = vec4(col, a);
}`;

const atmoVert = `
varying vec3 vNormal;
void main() {
  vNormal = normalize(normalMatrix * normal);
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

const atmoFrag = `
varying vec3 vNormal;
uniform vec3 uColor;
uniform float uPower;
uniform float uStrength;
void main() {
  float i = pow(clamp(0.78 - dot(vNormal, vec3(0.0, 0.0, 1.0)), 0.0, 1.0), uPower) * uStrength;
  gl_FragColor = vec4(uColor * i, i);
}`;

const coreFrag = `
varying vec3 vNormal;
void main() {
  float rim = 1.0 - clamp(dot(vNormal, vec3(0.0, 0.0, 1.0)), 0.0, 1.0);
  vec3 base = vec3(0.020, 0.035, 0.110);
  vec3 edge = vec3(0.20, 0.16, 0.55);
  gl_FragColor = vec4(mix(base, edge, pow(rim, 3.0)), 1.0);
}`;

const arcVert = `
varying float vU;
void main() {
  vU = uv.x;
  gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
}`;

const arcFrag = `
varying float vU;
uniform float uTime;
uniform float uOffset;
uniform float uReveal;
void main() {
  if (vU > uReveal) discard;
  float head = fract(uTime * 0.28 + uOffset) * 1.4 - 0.2;
  float trail = smoothstep(head - 0.28, head, vU) * (1.0 - step(head, vU));
  vec3 col = mix(vec3(0.33, 0.55, 1.0), vec3(0.62, 0.42, 1.0), vU);
  col = mix(col, vec3(0.75, 1.0, 0.96), trail * 0.6);
  float a = 0.16 + trail * 0.85;
  gl_FragColor = vec4(col, a);
}`;

/* ---------------- pieces ---------------- */

function Dots({ focus }: { focus: THREE.Vector3 | null }) {
  const [geo, setGeo] = useState<THREE.BufferGeometry | null>(null);
  const mat = useMemo(
    () =>
      new THREE.ShaderMaterial({
        vertexShader: dotsVert,
        fragmentShader: dotsFrag,
        transparent: true,
        depthWrite: false,
        uniforms: { uSize: { value: 5.2 }, uFocus: { value: new THREE.Vector3() }, uFocusOn: { value: 0 } },
      }),
    [],
  );

  useEffect(() => {
    let alive = true;
    fetch("/globe-dots.json")
      .then((r) => r.json())
      .then((flat: number[]) => {
        if (!alive) return;
        const pos = new Float32Array((flat.length / 2) * 3);
        for (let i = 0; i < flat.length; i += 2) {
          const v = latLngToVec3(flat[i], flat[i + 1], R * 1.001);
          pos.set([v.x, v.y, v.z], (i / 2) * 3);
        }
        const g = new THREE.BufferGeometry();
        g.setAttribute("position", new THREE.BufferAttribute(pos, 3));
        setGeo(g);
      });
    return () => {
      alive = false;
    };
  }, []);

  useFrame(() => {
    const u = mat.uniforms;
    u.uFocusOn.value += ((focus ? 1 : 0) - u.uFocusOn.value) * 0.06;
    if (focus) (u.uFocus.value as THREE.Vector3).lerp(focus, 0.2);
  });

  if (!geo) return null;
  return <points geometry={geo} material={mat} />;
}

function Arc({ from, to, offset, color }: { from: THREE.Vector3; to: THREE.Vector3; offset: number; color?: string }) {
  const { geo, mat } = useMemo(() => {
    const dist = from.distanceTo(to);
    const mid = from.clone().add(to).normalize().multiplyScalar(R + dist * 0.28);
    const curve = new THREE.QuadraticBezierCurve3(from.clone().multiplyScalar(1.002), mid, to.clone().multiplyScalar(1.002));
    const geo = new THREE.TubeGeometry(curve, 96, 0.0032, 6, false);
    const mat = new THREE.ShaderMaterial({
      vertexShader: arcVert,
      fragmentShader: arcFrag,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      uniforms: { uTime: { value: 0 }, uOffset: { value: offset }, uReveal: { value: 0 } },
    });
    return { geo, mat };
  }, [from, to, offset]);

  useEffect(() => () => { geo.dispose(); mat.dispose(); }, [geo, mat]);

  useFrame((s, dt) => {
    mat.uniforms.uTime.value = s.clock.elapsedTime;
    mat.uniforms.uReveal.value = Math.min(1, mat.uniforms.uReveal.value + dt * 1.4);
  });
  void color;
  return <mesh geometry={geo} material={mat} />;
}

function Marker({
  dc, selected, hovered, onHover, onSelect,
}: {
  dc: Datacenter; selected: boolean; hovered: boolean;
  onHover: (code: string | null) => void; onSelect: (code: string) => void;
}) {
  const pos = useMemo(() => latLngToVec3(dc.lat, dc.lng, R * 1.004), [dc]);
  const quat = useMemo(() => new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, 1), pos.clone().normalize()), [pos]);
  const ring = useRef<THREE.Mesh>(null);
  const beam = useRef<THREE.Mesh>(null);
  const soon = dc.status === "soon";
  const phase = useMemo(() => Math.random() * 2, []);

  useFrame((s) => {
    if (ring.current) {
      const t = ((s.clock.elapsedTime + phase) % 2.2) / 2.2;
      const k = 1 + t * (selected ? 3.2 : 2.2);
      ring.current.scale.setScalar(k);
      (ring.current.material as THREE.MeshBasicMaterial).opacity = (1 - t) * (soon ? 0.25 : 0.7);
    }
    if (beam.current) {
      const target = selected || hovered ? 1 : 0.001;
      beam.current.scale.z += (target - beam.current.scale.z) * 0.12;
    }
  });

  const color = soon ? "#7f89b8" : selected ? "#9df5ea" : "#8fb5ff";

  return (
    <group position={pos} quaternion={quat}>
      <mesh>
        <circleGeometry args={[selected ? 0.016 : 0.011, 20]} />
        <meshBasicMaterial color={color} transparent depthWrite={false} />
      </mesh>
      <mesh ref={ring}>
        <ringGeometry args={[0.013, 0.016, 32]} />
        <meshBasicMaterial color={soon ? "#7f89b8" : "#8b9dff"} transparent depthWrite={false} side={THREE.DoubleSide} />
      </mesh>
      <mesh ref={beam} position={[0, 0, 0]} scale={[1, 1, 0.001]}>
        <cylinderGeometry args={[0.0022, 0.0022, 0.14, 6]} />
        <meshBasicMaterial color={selected ? "#3be8d0" : "#8fb5ff"} transparent opacity={0.85} depthWrite={false} />
      </mesh>
      {/* the cylinder is Y-up, so rotate it to point outwards along local Z */}
      <group rotation={[Math.PI / 2, 0, 0]} />
      <mesh
        onPointerOver={(e: ThreeEvent<PointerEvent>) => { e.stopPropagation(); onHover(dc.code); document.body.style.cursor = "pointer"; }}
        onPointerOut={() => { onHover(null); document.body.style.cursor = ""; }}
        onClick={(e: ThreeEvent<MouseEvent>) => { e.stopPropagation(); onSelect(dc.code); }}
      >
        <sphereGeometry args={[0.05, 8, 8]} />
        <meshBasicMaterial transparent opacity={0} depthWrite={false} />
      </mesh>
      {hovered && (
        <Html position={[0, 0, 0.02]} center={false} zIndexRange={[20, 0]} style={{ pointerEvents: "none" }}>
          <div className="panel ml-4 -mt-4 w-max rounded-xl px-3 py-2 text-xs shadow-xl">
            <p className="font-medium text-ink">
              {dc.city} <span className="font-mono text-haze">{dc.code}</span>
            </p>
            <p className="mt-0.5 text-haze">{soon ? "Opening soon" : dc.products.join(", ")}</p>
          </div>
        </Html>
      )}
    </group>
  );
}

type RotState = { x: number; y: number; vx: number; vy: number; target: { x: number; y: number } | null; lastInput: number };

function GlobeScene({
  datacenters, selected, hovered, onHover, onSelect, rot,
}: {
  datacenters: Datacenter[]; selected: string | null; hovered: string | null;
  onHover: (c: string | null) => void; onSelect: (c: string) => void; rot: React.RefObject<RotState>;
}) {
  const group = useRef<THREE.Group>(null);
  const byCode = useMemo(() => Object.fromEntries(datacenters.map((d) => [d.code, d])), [datacenters]);
  const vec = useMemo(() => Object.fromEntries(datacenters.map((d) => [d.code, latLngToVec3(d.lat, d.lng)])), [datacenters]);
  const reduced = useMemo(() => typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches, []);

  const arcs = useMemo(() => {
    if (selected && byCode[selected]) {
      return datacenters
        .filter((d) => d.code !== selected && d.status === "online")
        .map((d, i) => ({ key: `${selected}-${d.code}`, from: vec[selected], to: vec[d.code], offset: i * 0.13 }));
    }
    return BACKBONE.map(([a, b], i) => ({ key: `${a}-${b}`, from: vec[a], to: vec[b], offset: i * 0.21 }));
  }, [selected, byCode, datacenters, vec]);

  useFrame((_, dt) => {
    const r = rot.current;
    const g = group.current;
    if (!r || !g) return;
    const idle = performance.now() - r.lastInput > 2500;
    if (r.target) {
      let dy = r.target.y - r.y;
      dy = Math.atan2(Math.sin(dy), Math.cos(dy)); // shortest way round
      r.y += dy * Math.min(1, dt * 3.2);
      r.x += (r.target.x - r.x) * Math.min(1, dt * 3.2);
      if (Math.abs(dy) < 0.001 && Math.abs(r.target.x - r.x) < 0.001) r.target = null;
    } else {
      r.y += r.vy;
      r.x += r.vx;
      r.vx *= 0.93;
      r.vy *= 0.93;
      if (idle && !selected && !reduced) r.y += dt * 0.08;
      if (idle) r.x += (0.32 - r.x) * dt * 0.4;
    }
    r.x = Math.max(-1.1, Math.min(1.1, r.x));
    g.rotation.set(r.x, r.y, 0, "XYZ");
  });

  return (
    <>
      <group ref={group}>
        <mesh onPointerOver={(e) => e.stopPropagation()} onClick={(e) => e.stopPropagation()}>
          <sphereGeometry args={[R * 0.995, 96, 96]} />
          <shaderMaterial vertexShader={atmoVert} fragmentShader={coreFrag} />
        </mesh>
        <Dots focus={selected ? vec[selected] : null} />
        {arcs.map((a) => (
          <Arc key={a.key} from={a.from} to={a.to} offset={a.offset} />
        ))}
        {datacenters.map((d) => (
          <Marker key={d.code} dc={d} selected={selected === d.code} hovered={hovered === d.code} onHover={onHover} onSelect={onSelect} />
        ))}
      </group>
      {/* outer glow */}
      <mesh scale={1.22}>
        <sphereGeometry args={[R, 64, 64]} />
        <shaderMaterial
          vertexShader={atmoVert}
          fragmentShader={atmoFrag}
          side={THREE.BackSide}
          blending={THREE.AdditiveBlending}
          transparent
          depthWrite={false}
          uniforms={{ uColor: { value: new THREE.Color("#5d4bff") }, uPower: { value: 3.2 }, uStrength: { value: 1.25 } }}
        />
      </mesh>
    </>
  );
}

export type GlobeProps = {
  datacenters: Datacenter[];
  selected: string | null;
  onSelect: (code: string) => void;
  focusRequest?: { lat: number; lng: number; n: number } | null;
};

export default function Globe({ datacenters, selected, onSelect, focusRequest }: GlobeProps) {
  const [hovered, setHovered] = useState<string | null>(null);
  const [inView, setInView] = useState(true);
  const wrap = useRef<HTMLDivElement>(null);
  const rot = useRef<RotState>({ x: 0.32, y: facingRotation(20, -30).y, vx: 0, vy: 0, target: null, lastInput: 0 });
  const drag = useRef<{ x: number; y: number; id: number } | null>(null);

  useEffect(() => {
    const d = datacenters.find((x) => x.code === selected);
    if (d) {
      rot.current.target = facingRotation(d.lat, d.lng);
      rot.current.target.x = Math.max(-0.9, Math.min(0.9, rot.current.target.x));
    }
  }, [selected, datacenters]);

  useEffect(() => {
    if (focusRequest) rot.current.target = facingRotation(focusRequest.lat, focusRequest.lng);
  }, [focusRequest]);

  useEffect(() => {
    const el = wrap.current;
    if (!el) return;
    const io = new IntersectionObserver(([e]) => setInView(e.isIntersecting), { rootMargin: "100px" });
    io.observe(el);
    return () => io.disconnect();
  }, []);

  return (
    <div
      ref={wrap}
      className="relative aspect-square w-full cursor-grab touch-pan-y select-none active:cursor-grabbing"
      onPointerDown={(e) => {
        drag.current = { x: e.clientX, y: e.clientY, id: e.pointerId };
        rot.current.target = null;
        rot.current.lastInput = performance.now();
      }}
      onPointerMove={(e) => {
        const d = drag.current;
        if (!d || d.id !== e.pointerId) return;
        const dx = e.clientX - d.x;
        const dy = e.clientY - d.y;
        if (Math.abs(dx) + Math.abs(dy) > 3) (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
        d.x = e.clientX;
        d.y = e.clientY;
        const r = rot.current;
        r.vy = dx * 0.0055;
        r.vx = dy * 0.0055;
        r.y += r.vy;
        r.x += r.vx;
        r.lastInput = performance.now();
      }}
      onPointerUp={() => (drag.current = null)}
      onPointerCancel={() => (drag.current = null)}
    >
      <Canvas
        frameloop={inView ? "always" : "never"}
        dpr={[1, 2]}
        camera={{ position: [0, 0, 3.1], fov: 42 }}
        gl={{ antialias: true, alpha: true, powerPreference: "high-performance" }}
        onPointerMissed={() => setHovered(null)}
      >
        <GlobeScene
          datacenters={datacenters}
          selected={selected}
          hovered={hovered}
          onHover={setHovered}
          onSelect={onSelect}
          rot={rot}
        />
      </Canvas>
    </div>
  );
}

