        <meshBasicMaterial color={soon ? "#7f89b8" : "#8b9dff"} transparent depthWrite={false} side={THREE.DoubleSide} />
      </mesh>
      <mesh ref={beam} position={[0, 0, 0]} scale={[1, 1, 0.001]}>
        <cylinderGeometry args={[0.0022, 0.0022, 0.14, 6]} />
        <meshBasicMaterial color={selected ? "#3be8d0" : "#8fb5ff"} transparent opacity={0.85} depthWrite={false} />
      </mesh>
      {/* the cylinder is Y-up, so rotate it to point outwards along local Z */}
      <group rotation={[Math.PI / 2, 0, 0]} />
      <mesh
        onPointerOver={(e: ThreeEvent<PointerEvent>) => { e.stopPropagation(); onHover(dc.code); document.body.style.cursor = "pointer"; }}
        onPointerOut={() => { onHover(null); document.body.style.cursor = ""; }}
        onClick={(e: ThreeEvent<MouseEvent>) => { e.stopPropagation(); onSelect(dc.code); }}
      >
        <sphereGeometry args={[0.05, 8, 8]} />
        <meshBasicMaterial transparent opacity={0} depthWrite={false} />
      </mesh>
      {hovered && (
        <Html position={[0, 0, 0.02]} center={false} zIndexRange={[20, 0]} style={{ pointerEvents: "none" }}>
          <div className="panel ml-4 -mt-4 w-max rounded-xl px-3 py-2 text-xs shadow-xl">
            <p className="font-medium text-ink">
              {dc.city} <span className="font-mono text-haze">{dc.code}</span>
            </p>
            <p className="mt-0.5 text-haze">{soon ? "Opening soon" : dc.products.join(", ")}</p>
          </div>
        </Html>
      )}
    </group>
  );
}

type RotState = { x: number; y: number; vx: number; vy: number; target: { x: number; y: number } | null; lastInput: number };

function GlobeScene({
  datacenters, selected, hovered, onHover, onSelect, rot,
}: {
  datacenters: Datacenter[]; selected: string | null; hovered: string | null;
  onHover: (c: string | null) => void; onSelect: (c: string) => void; rot: React.RefObject<RotState>;
}) {
  const group = useRef<THREE.Group>(null);
  const byCode = useMemo(() => Object.fromEntries(datacenters.map((d) => [d.code, d])), [datacenters]);
  const vec = useMemo(() => Object.fromEntries(datacenters.map((d) => [d.code, latLngToVec3(d.lat, d.lng)])), [datacenters]);
  const reduced = useMemo(() => typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches, []);

  const arcs = useMemo(() => {
    if (selected && byCode[selected]) {
      return datacenters
        .filter((d) => d.code !== selected && d.status === "online")
        .map((d, i) => ({ key: `${selected}-${d.code}`, from: vec[selected], to: vec[d.code], offset: i * 0.13 }));
    }
    return BACKBONE.map(([a, b], i) => ({ key: `${a}-${b}`, from: vec[a], to: vec[b], offset: i * 0.21 }));
  }, [selected, byCode, datacenters, vec]);

  useFrame((_, dt) => {
    const r = rot.current;
    const g = group.current;
    if (!r || !g) return;
    const idle = performance.now() - r.lastInput > 2500;
    if (r.target) {
      let dy = r.target.y - r.y;
      dy = Math.atan2(Math.sin(dy), Math.cos(dy)); // shortest way round
      r.y += dy * Math.min(1, dt * 3.2);
      r.x += (r.target.x - r.x) * Math.min(1, dt * 3.2);
      if (Math.abs(dy) < 0.001 && Math.abs(r.target.x - r.x) < 0.001) r.target = null;
    } else {
      r.y += r.vy;
      r.x += r.vx;
      r.vx *= 0.93;
      r.vy *= 0.93;
      if (idle && !selected && !reduced) r.y += dt * 0.08;
      if (idle) r.x += (0.32 - r.x) * dt * 0.4;
    }
    r.x = Math.max(-1.1, Math.min(1.1, r.x));
    g.rotation.set(r.x, r.y, 0, "XYZ");
  });

  return (
    <>
      <group ref={group}>
        <mesh onPointerOver={(e) => e.stopPropagation()} onClick={(e) => e.stopPropagation()}>
          <sphereGeometry args={[R * 0.995, 96, 96]} />
          <shaderMaterial vertexShader={atmoVert} fragmentShader={coreFrag} />
        </mesh>
        <Dots focus={selected ? vec[selected] : null} />
        {arcs.map((a) => (
          <Arc key={a.key} from={a.from} to={a.to} offset={a.offset} />
        ))}
        {datacenters.map((d) => (
          <Marker key={d.code} dc={d} selected={selected === d.code} hovered={hovered === d.code} onHover={onHover} onSelect={onSelect} />
        ))}
      </group>
      {/* outer glow */}
      <mesh scale={1.22}>
        <sphereGeometry args={[R, 64, 64]} />
        <shaderMaterial
          vertexShader={atmoVert}
          fragmentShader={atmoFrag}
          side={THREE.BackSide}
          blending={THREE.AdditiveBlending}
          transparent
          depthWrite={false}
          uniforms={{ uColor: { value: new THREE.Color("#5d4bff") }, uPower: { value: 3.2 }, uStrength: { value: 1.25 } }}
        />
      </mesh>
    </>
  );
}

export type GlobeProps = {
  datacenters: Datacenter[];
  selected: string | null;
  onSelect: (code: string) => void;
  focusRequest?: { lat: number; lng: number; n: number } | null;
};

export default function Globe({ datacenters, selected, onSelect, focusRequest }: GlobeProps) {
  const [hovered, setHovered] = useState<string | null>(null);
  const [inView, setInView] = useState(true);
  const wrap = useRef<HTMLDivElement>(null);
  const rot = useRef<RotState>({ x: 0.32, y: facingRotation(20, -30).y, vx: 0, vy: 0, target: null, lastInput: 0 });
  const drag = useRef<{ x: number; y: number; id: number } | null>(null);

  useEffect(() => {
    const d = datacenters.find((x) => x.code === selected);
    if (d) {
      rot.current.target = facingRotation(d.lat, d.lng);
      rot.current.target.x = Math.max(-0.9, Math.min(0.9, rot.current.target.x));
    }
  }, [selected, datacenters]);

  useEffect(() => {
    if (focusRequest) rot.current.target = facingRotation(focusRequest.lat, focusRequest.lng);
  }, [focusRequest]);

  useEffect(() => {
    const el = wrap.current;
    if (!el) return;
    const io = new IntersectionObserver(([e]) => setInView(e.isIntersecting), { rootMargin: "100px" });
    io.observe(el);
    return () => io.disconnect();
  }, []);

  return (
    <div
      ref={wrap}
      className="relative aspect-square w-full cursor-grab touch-pan-y select-none active:cursor-grabbing"
      onPointerDown={(e) => {
        drag.current = { x: e.clientX, y: e.clientY, id: e.pointerId };
        rot.current.target = null;
        rot.current.lastInput = performance.now();
      }}
      onPointerMove={(e) => {
        const d = drag.current;
        if (!d || d.id !== e.pointerId) return;
        const dx = e.clientX - d.x;
        const dy = e.clientY - d.y;
        if (Math.abs(dx) + Math.abs(dy) > 3) (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId);
        d.x = e.clientX;
        d.y = e.clientY;
        const r = rot.current;
        r.vy = dx * 0.0055;
        r.vx = dy * 0.0055;
        r.y += r.vy;
        r.x += r.vx;
        r.lastInput = performance.now();
      }}
      onPointerUp={() => (drag.current = null)}
      onPointerCancel={() => (drag.current = null)}
    >
      <Canvas
        frameloop={inView ? "always" : "never"}
        dpr={[1, 2]}
        camera={{ position: [0, 0, 3.1], fov: 42 }}
        gl={{ antialias: true, alpha: true, powerPreference: "high-performance" }}
        onPointerMissed={() => setHovered(null)}
      >
        <GlobeScene
          datacenters={datacenters}
          selected={selected}
          hovered={hovered}
          onHover={setHovered}
          onSelect={onSelect}
          rot={rot}
        />
      </Canvas>
    </div>
  );
}

