import { DATACENTERS, type Datacenter } from "./datacenters";

export function distanceKm(a: { lat: number; lng: number }, b: { lat: number; lng: number }) {
  const toRad = Math.PI / 180;
  const dLat = (b.lat - a.lat) * toRad;
  const dLng = (b.lng - a.lng) * toRad;
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * toRad) * Math.cos(b.lat * toRad) * Math.sin(dLng / 2) ** 2;
  return 2 * 6371 * Math.asin(Math.sqrt(h));
}

/** Light in fibre covers ~200 km per ms; routes are never straight, so pad by 30% plus a hop allowance. */
export function estimateRttMs(km: number) {
  return Math.max(2, Math.round((km / 100) * 1.3 + 3));
}

const SOUTH_AMERICA = /Sao_Paulo|Argentina|Santiago|Lima|Bogota|Caracas|Montevideo|La_Paz|Asuncion|Recife|Fortaleza|Belem|Manaus/;

/**
 * A rough location from the browser time zone alone, no permission prompt.
 * Longitude comes from the UTC offset, latitude from the zone's region.
 */
export function guessLocationFromTimeZone(): { lat: number; lng: number; zone: string } | null {
  try {
    const zone = Intl.DateTimeFormat().resolvedOptions().timeZone ?? "";
    const offsetHours = -new Date().getTimezoneOffset() / 60;
    let lng = offsetHours * 15;
    const region = zone.split("/")[0];
    let lat = 30;
    if (region === "Europe") lat = 50;
    else if (region === "America") lat = SOUTH_AMERICA.test(zone) ? -18 : 38;
    else if (region === "Asia") lat = /Kolkata|Calcutta|Dubai|Karachi|Dhaka|Colombo/.test(zone) ? 22 : /Singapore|Jakarta|Kuala_Lumpur|Manila|Bangkok|Ho_Chi_Minh/.test(zone) ? 5 : 33;
    else if (region === "Australia") lat = -32;
    else if (region === "Africa") lat = /Johannesburg|Harare|Maputo|Windhoek/.test(zone) ? -26 : 8;
    else if (region === "Pacific") lat = -20;
    if (zone === "Asia/Kolkata" || zone === "Asia/Calcutta") lng = 77;
    return { lat, lng, zone };
  } catch {
    return null;
  }
}

export function nearestDatacenter(from: { lat: number; lng: number }): { dc: Datacenter; km: number } {
  let best = DATACENTERS[0];
  let bestKm = Infinity;
  for (const dc of DATACENTERS) {
    if (dc.status !== "online") continue;
    const km = distanceKm(from, dc);
    if (km < bestKm) {
      best = dc;
      bestKm = km;
    }
  }
  return { dc: best, km: bestKm };
}

