"use client";

import dynamic from "next/dynamic";
import { useEffect, useMemo, useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { LocateFixed, MapPin } from "lucide-react";
import { DATACENTERS, ONLINE_COUNT, type Continent } from "@/lib/datacenters";
import { distanceKm, estimateRttMs, guessLocationFromTimeZone, nearestDatacenter } from "@/lib/geo";

const Globe = dynamic(() => import("./Globe"), {
  ssr: false,
  loading: () => (
    <div className="grid aspect-square w-full place-items-center">
      <div className="size-[70%] rounded-full bg-[radial-gradient(circle_at_40%_35%,#1a2466,#060c24_70%)] shadow-[0_0_120px_rgb(93_75_255/0.35)]" />
    </div>
  ),
});

const CONTINENTS: Continent[] = ["Americas", "Europe", "Asia Pacific", "Middle East & Africa"];

export function GlobeSection() {
  const [selected, setSelected] = useState<string | null>(null);
  const [filter, setFilter] = useState<Continent | "All">("All");
  const [me, setMe] = useState<{ lat: number; lng: number; zone: string } | null>(null);

  useEffect(() => setMe(guessLocationFromTimeZone()), []);

  const sel = DATACENTERS.find((d) => d.code === selected) ?? null;
  const list = useMemo(() => DATACENTERS.filter((d) => filter === "All" || d.continent === filter), [filter]);
  const nearest = useMemo(() => (me ? nearestDatacenter(me) : null), [me]);

  const toggle = (code: string) => setSelected((s) => (s === code ? null : code));

  return (
    <section id="network" aria-labelledby="network-title" className="relative scroll-mt-20 overflow-hidden py-24 sm:py-32">
      <div className="pointer-events-none absolute inset-x-0 top-1/2 -z-10 h-[700px] -translate-y-1/2 bg-[radial-gradient(50%_50%_at_70%_50%,rgb(61_40_190/0.28),transparent_70%)]" />

      <div className="mx-auto max-w-6xl px-4 sm:px-6">
        <div className="grid items-center gap-10 lg:grid-cols-[0.9fr_1.1fr] lg:gap-6">
          <div className="relative z-10">
            <h2 id="network-title" className="text-balance font-display text-[clamp(1.8rem,3.6vw,2.8rem)] font-normal leading-[1.1] tracking-[-0.03em]">
              Close to your users, wherever they are
            </h2>
            <p className="mt-4 max-w-md text-pretty text-[17px] leading-relaxed text-mist">
              {ONLINE_COUNT} regions on a private backbone, with two more opening this year. Pick a city to see how it connects.
            </p>

            {nearest && (
              <button
                type="button"
                onClick={() => setSelected(nearest.dc.code)}
                className="mt-7 flex w-full max-w-md cursor-pointer items-center gap-3 rounded-2xl border border-aurora/25 bg-aurora/[0.06] p-3.5 text-left transition-colors hover:bg-aurora/[0.1]"
              >
                <span className="grid size-10 shrink-0 place-items-center rounded-xl bg-aurora/15 text-aurora">
                  <LocateFixed className="size-5" />
                </span>
                <span className="min-w-0">
                  <span className="block text-sm text-ink">
                    Your nearest region is {nearest.dc.city}, about {estimateRttMs(nearest.km)} ms away
                  </span>
                  <span className="block truncate text-xs text-haze">Estimated from your time zone ({me?.zone.replace(/_/g, " ")}). Nothing leaves your browser.</span>
                </span>
              </button>
            )}

            <div className="mt-7 flex flex-wrap gap-1.5" role="group" aria-label="Filter regions">
              {(["All", ...CONTINENTS] as const).map((c) => (
                <button
                  key={c}
                  type="button"
                  aria-pressed={filter === c}
                  onClick={() => setFilter(c)}
                  className={`cursor-pointer rounded-lg px-3 py-1.5 text-[13px] transition-colors ${
                    filter === c ? "bg-white/10 text-ink" : "text-haze hover:text-mist"
                  }`}
                >
                  {c}
                </button>
              ))}
            </div>

            <ul className="mt-3 grid max-w-md grid-cols-2 gap-1 sm:grid-cols-3">
              {list.map((d) => (
                <li key={d.code}>
                  <button
                    type="button"
                    aria-pressed={selected === d.code}
                    onClick={() => toggle(d.code)}
                    className={`flex w-full cursor-pointer items-center gap-2 rounded-lg px-2.5 py-2 text-left text-sm transition-colors ${
                      selected === d.code ? "bg-nx/20 text-ink" : "text-mist hover:bg-white/[0.04] hover:text-ink"
                    }`}
                  >
                    <span className={`size-1.5 shrink-0 rounded-full ${d.status === "online" ? "bg-nx-soft" : "border border-haze"}`} />
                    <span className="truncate">{d.city}</span>
                  </button>
                </li>
              ))}
            </ul>

            <div className="mt-5 min-h-[128px] max-w-md">
              <AnimatePresence mode="wait">
                {sel ? (
                  <motion.div
                    key={sel.code}
                    initial={{ opacity: 0, y: 8 }}
                    animate={{ opacity: 1, y: 0 }}
                    exit={{ opacity: 0, y: -8 }}
                    transition={{ duration: 0.25 }}
                    className="panel rounded-2xl p-4"
                  >
                    <div className="flex items-start justify-between gap-3">
                      <div>
                        <p className="flex items-center gap-2 text-ink">
                          <MapPin className="size-4 text-nx-soft" /> {sel.city}, {sel.country}
                        </p>
                        <p className="mt-0.5 font-mono text-xs text-haze">{sel.code.toLowerCase()}</p>
                      </div>
                      <span
                        className={`rounded-full px-2.5 py-1 text-xs ${
                          sel.status === "online" ? "bg-aurora/10 text-aurora" : "bg-white/5 text-mist"
                        }`}
                      >
                        {sel.status === "online" ? "Online" : "Opening soon"}
                      </span>
                    </div>
                    <dl className="mt-4 grid grid-cols-3 gap-3 text-sm">
                      <div>
                        <dt className="text-xs text-haze">Available</dt>
                        <dd className="mt-0.5 text-ink">{sel.products.join(", ")}</dd>
                      </div>
                      <div>
                        <dt className="text-xs text-haze">To local exchange</dt>
                        <dd className="mt-0.5 tabular-nums text-ink">{sel.latency} ms</dd>
                      </div>
                      {me && (
                        <div>
                          <dt className="text-xs text-haze">From you, est.</dt>
                          <dd className="mt-0.5 tabular-nums text-ink">{estimateRttMs(distanceKm(me, sel))} ms</dd>
                        </div>
                      )}
                    </dl>
                  </motion.div>
                ) : (
                  <motion.p key="hint" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="pt-2 text-sm text-haze">
                    Drag the globe to spin it. Hover a point for its name, click it to see routes.
                  </motion.p>
                )}
              </AnimatePresence>
            </div>
          </div>

          <div className="relative -mx-4 sm:mx-0 lg:-mr-24">
            <Globe datacenters={DATACENTERS} selected={selected} onSelect={toggle} />
          </div>
        </div>
      </div>
    </section>
  );
}

