  { cpu: 8, ram: 16, disk: 320, transfer: 8, price: 32 },
  { cpu: 16, ram: 32, disk: 640, transfer: 10, price: 64 },
  { cpu: 32, ram: 64, disk: 1280, transfer: 12, price: 128 },
];

const GAMES = [
  { id: "minecraft", name: "Minecraft", base: 2, perPlayer: 0.12, max: 100 },
  { id: "rust", name: "Rust", base: 6, perPlayer: 0.08, max: 200 },
  { id: "palworld", name: "Palworld", base: 8, perPlayer: 0.25, max: 32 },
  { id: "valheim", name: "Valheim", base: 3, perPlayer: 0.2, max: 10 },
  { id: "cs2", name: "CS2", base: 2, perPlayer: 0.06, max: 64 },
  { id: "ark", name: "ARK", base: 8, perPlayer: 0.15, max: 70 },
];

const INCLUDED = [
  "DDoS filtering up to 2.4 Tbps",
  "IPv4 address and IPv6 /64",
  "Hourly billing, cancel any time",
  "99.99% uptime SLA",
  "Free snapshots, 3 kept",
  "Human support around the clock",
];

function Num({ value, decimals = 0 }: { value: number; decimals?: number }) {
  const ref = useRef<HTMLSpanElement>(null);
  const prev = useRef(value);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    const controls = animate(prev.current, value, {
      duration: 0.5,
      ease: [0.16, 1, 0.3, 1],
      onUpdate: (v) => (el.textContent = v.toFixed(decimals)),
    });
    prev.current = value;
    return () => controls.stop();
  }, [value, decimals]);
  return <span ref={ref}>{value.toFixed(decimals)}</span>;
}

export function Configurator() {
  const [kind, setKind] = useState<"vps" | "game">("vps");
  const [planIdx, setPlanIdx] = useState(2);
  const [gameId, setGameId] = useState("minecraft");
  const [players, setPlayers] = useState(20);
  const [hourly, setHourly] = useState(false);
  const [region, setRegion] = useState("FRA1");

  const game = GAMES.find((g) => g.id === gameId)!;
  const plan = VPS_PLANS[planIdx];

  useEffect(() => setPlayers((p) => Math.min(p, game.max)), [game.max]);

  const result = useMemo(() => {
    if (kind === "vps") return { monthly: plan.price, label: `${plan.cpu} vCPU cloud server` };
    const ram = Math.max(2, Math.ceil(game.base + game.perPlayer * players));
    return { monthly: ram * 1.0, ram, label: `${game.name} server for ${players} players` };
  }, [kind, plan, game, players]);

  const regions = DATACENTERS.filter((d) => d.status === "online" && (kind === "vps" || d.products.includes("Game")));
  const price = hourly ? result.monthly / 730 : result.monthly;

  return (
    <section id="pricing" aria-labelledby="pricing-title" className="relative scroll-mt-20 py-24 sm:py-32">
      <div className="mx-auto max-w-6xl px-4 sm:px-6">
        <div className="max-w-2xl">
          <h2 id="pricing-title" className="text-balance font-display text-[clamp(1.8rem,3.6vw,2.8rem)] font-normal leading-[1.1] tracking-[-0.03em]">
            Pick the size, see the price
          </h2>
          <p className="mt-4 max-w-xl text-pretty text-[17px] leading-relaxed text-mist">
            No setup fees and no bandwidth surprises. What you see here is what shows up on the invoice.
          </p>
        </div>

        <div className="panel mt-12 grid overflow-hidden rounded-[28px] lg:grid-cols-[1.35fr_1fr]">
          {/* controls */}
          <div className="p-6 sm:p-9">
            <div role="tablist" aria-label="Server type" className="inline-grid grid-cols-2 rounded-xl border border-[var(--line)] bg-abyss/50 p-1">
              {([
                ["vps", "Cloud VPS"],
                ["game", "Game server"],
              ] as const).map(([k, label]) => (
                <button
                  key={k}
                  role="tab"
                  aria-selected={kind === k}
                  onClick={() => setKind(k)}
                  className={`relative cursor-pointer rounded-lg px-4 py-2 text-sm transition-colors ${kind === k ? "text-ink" : "text-haze hover:text-mist"}`}
                >
                  {kind === k && (
                    <motion.span layoutId="kind-pill" className="absolute inset-0 -z-0 rounded-lg bg-white/10" transition={{ type: "spring", stiffness: 420, damping: 36 }} />
                  )}
                  <span className="relative">{label}</span>
                </button>
              ))}
            </div>

            {kind === "vps" ? (
              <div className="mt-8">
                <label htmlFor="plan" className="flex items-baseline justify-between text-sm text-mist">
                  <span>Server size</span>
                  <span className="font-display text-ink">{plan.cpu} vCPU</span>
                </label>
                <input
                  id="plan"
                  type="range"
                  min={0}
                  max={VPS_PLANS.length - 1}
                  step={1}
                  value={planIdx}
                  onChange={(e) => setPlanIdx(+e.target.value)}
                  className="nx-range mt-4 w-full"
                  style={{ ["--fill" as string]: `${(planIdx / (VPS_PLANS.length - 1)) * 100}%` }}
                  aria-valuetext={`${plan.cpu} vCPU, ${plan.ram} GB memory`}
                />
                <div className="mt-2 flex justify-between text-xs text-haze" aria-hidden="true">
                  {VPS_PLANS.map((p) => (
                    <span key={p.cpu}>{p.cpu}</span>
                  ))}
                </div>

                <dl className="mt-8 grid grid-cols-2 gap-3 sm:grid-cols-4">
                  {[
                    { icon: Cpu, k: "vCPU", v: plan.cpu, u: "" },
                    { icon: MemoryStick, k: "Memory", v: plan.ram, u: "GB" },
                    { icon: HardDrive, k: "NVMe", v: plan.disk, u: "GB" },
                    { icon: Gauge, k: "Transfer", v: plan.transfer, u: "TB" },
                  ].map(({ icon: Icon, k, v, u }) => (
                    <div key={k} className="rounded-xl border border-[var(--line)] p-3.5">
                      <dt className="flex items-center gap-1.5 text-xs text-haze">
                        <Icon className="size-3.5" /> {k}
                      </dt>
                      <dd className="mt-1.5 font-display text-lg tabular-nums text-ink">
                        <Num value={v} /> <span className="text-xs text-haze">{u}</span>
                      </dd>
                    </div>
                  ))}
                </dl>
              </div>
            ) : (
              <div className="mt-8">
                <p className="text-sm text-mist" id="game-label">
                  Game
                </p>
                <div className="mt-3 flex flex-wrap gap-2" role="radiogroup" aria-labelledby="game-label">
                  {GAMES.map((g) => (
                    <button
                      key={g.id}
                      role="radio"
                      aria-checked={gameId === g.id}
                      onClick={() => setGameId(g.id)}
                      className={`cursor-pointer rounded-xl border px-3.5 py-2 text-sm transition-colors ${
                        gameId === g.id ? "border-violet/60 bg-violet/15 text-ink" : "border-[var(--line)] text-mist hover:text-ink"
                      }`}
                    >
                      {g.name}
                    </button>
                  ))}
                </div>

                <label htmlFor="players" className="mt-8 flex items-baseline justify-between text-sm text-mist">
                  <span className="flex items-center gap-1.5">
                    <Users className="size-4" /> Players online at once
                  </span>
                  <span className="font-display tabular-nums text-ink">{players}</span>
                </label>
                <input
                  id="players"
                  type="range"
                  min={2}
                  max={game.max}
                  value={players}
                  onChange={(e) => setPlayers(+e.target.value)}
                  className="nx-range mt-4 w-full"
                  style={{ ["--fill" as string]: `${((players - 2) / (game.max - 2)) * 100}%` }}
                />
                <p className="mt-6 rounded-xl border border-[var(--line)] p-4 text-sm text-mist">
                  We recommend <span className="font-display text-ink">{result.ram} GB</span> of memory for {players} {game.name} players. You can resize later without losing your world.
                </p>
              </div>
            )}

            <div className="mt-8">
              <label htmlFor="region" className="text-sm text-mist">
                Region
              </label>
              <select
                id="region"
                value={regions.some((r) => r.code === region) ? region : regions[0]?.code}
                onChange={(e) => setRegion(e.target.value)}
                className="mt-2 block w-full cursor-pointer appearance-none rounded-xl border border-[var(--line-strong)] bg-navy-950 bg-[url('data:image/svg+xml;utf8,<svg xmlns=%22http://www.w3.org/2000/svg%22 width=%2212%22 height=%2212%22 viewBox=%220 0 24 24%22 fill=%22none%22 stroke=%22%23a3acd1%22 stroke-width=%222%22><path d=%22m6 9 6 6 6-6%22/></svg>')] bg-[position:right_14px_center] bg-no-repeat px-4 py-3 text-[15px] text-ink sm:max-w-xs"
              >
                {regions.map((r) => (
                  <option key={r.code} value={r.code}>
                    {r.city}, {r.country}
                  </option>
                ))}
              </select>
            </div>
          </div>

          {/* summary */}
          <div className="relative flex flex-col border-t border-[var(--line)] bg-[linear-gradient(160deg,rgb(21_112_255/0.12),rgb(139_92_246/0.14))] p-6 sm:p-9 lg:border-l lg:border-t-0">
            <div className="flex items-center justify-between">
              <p className="text-sm text-mist">{result.label}</p>
              <button
                type="button"
                onClick={() => setHourly((h) => !h)}
                role="switch"
                aria-checked={hourly}
                className="flex cursor-pointer items-center gap-2 text-xs text-haze"
              >
                Hourly
                <span className={`relative h-5 w-9 rounded-full transition-colors ${hourly ? "bg-nx" : "bg-white/15"}`}>
                  <span className={`absolute top-0.5 size-4 rounded-full bg-white transition-transform ${hourly ? "translate-x-4" : "translate-x-0.5"}`} />
                </span>
              </button>
            </div>
            <p className="mt-4 font-display text-[3.4rem] font-light leading-none tracking-[-0.04em] text-ink">
              $<Num value={price} decimals={hourly ? 3 : 2} />
              <span className="ml-1 text-base font-normal tracking-normal text-haze">/{hourly ? "hour" : "month"}</span>
            </p>
            {hourly && <p className="mt-2 text-xs text-haze">Capped at ${result.monthly.toFixed(2)} a month</p>}

            <ul className="mt-8 space-y-2.5 text-[15px] text-mist">
              {INCLUDED.map((x) => (
                <li key={x} className="flex gap-2.5">
                  <Check className="mt-1 size-4 shrink-0 text-aurora" /> {x}
                </li>
              ))}
            </ul>

            <a
              href="#"
              className="mt-auto flex h-12 items-center justify-center rounded-xl bg-ink font-medium text-abyss transition-[transform,background] hover:bg-white active:scale-[0.98] max-lg:mt-8"
            >
              Deploy this server
            </a>
            <p className="mt-3 text-center text-xs text-haze">Ready in about 40 seconds</p>
          </div>
        </div>
      </div>
    </section>
  );
}

