"use client";

import { useState } from "react";
import { AnimatePresence, motion } from "motion/react";
import { Check, Copy, Webhook, Network, FileCode2, KeyRound } from "lucide-react";

const SNIPPETS = {
  CLI: `# install once
curl -fsSL https://get.nxeon.com | sh

# create a server and wait until it's reachable
nx servers create api-01 \\
  --plan vps-4 --region fra1 \\
  --image ubuntu-24.04 --ssh-key laptop --wait

nx ssh api-01`,
  cURL: `curl https://api.nxeon.com/v1/servers \\
  -H "Authorization: Bearer $NXEON_TOKEN" \\
  -H "Content-Type: application/json" \\
  -d '{
    "name": "api-01",
    "plan": "vps-4",
    "region": "fra1",
    "image": "ubuntu-24.04"
  }'`,
  Terraform: `terraform {
  required_providers {
    nxeon = { source = "nxeon/nxeon" }
  }
}

resource "nxeon_server" "api" {
  name   = "api-01"
  plan   = "vps-4"
  region = "fra1"
  image  = "ubuntu-24.04"
}`,
  "Node.js": `import { Nxeon } from "@nxeon/sdk";

const nx = new Nxeon({ token: process.env.NXEON_TOKEN });

const server = await nx.servers.create({
  name: "api-01",
  plan: "vps-4",
  region: "fra1",
  image: "ubuntu-24.04",
});

console.log(server.ipv4); // 203.0.113.42`,
} as const;

type Lang = keyof typeof SNIPPETS;

// Just enough highlighting for four short snippets.
function highlight(code: string) {
  const re = /(#[^\n]*|\/\/[^\n]*)|("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')|(\s--?[a-z][\w-]*)|\b(import|from|const|await|new|resource|terraform|required_providers|curl|nx)\b|(\$\w+)/g;
  const out: React.ReactNode[] = [];
  let last = 0;
  let m: RegExpExecArray | null;
  let i = 0;
  while ((m = re.exec(code))) {
    if (m.index > last) out.push(code.slice(last, m.index));
    const [t] = m;
    const cls = m[1] ? "text-haze italic" : m[2] ? "text-[#9ee6d9]" : m[3] ? "text-nx-soft" : m[4] ? "text-[#c4a8ff]" : "text-[#f5c07a]";
    out.push(<span key={i++} className={cls}>{t}</span>);
    last = m.index + t.length;
  }
  out.push(code.slice(last));
  return out;
}

const FEATURES = [
  { icon: KeyRound, title: "Scoped API tokens", body: "Read-only, per-project or full access. Rotate without downtime." },
  { icon: FileCode2, title: "cloud-init on boot", body: "Pass a script, get a configured server. No golden images to maintain." },
  { icon: Network, title: "Private networking", body: "Servers in different regions talk over our backbone, not the internet." },
  { icon: Webhook, title: "Webhooks", body: "Get a POST when a server boots, a backup finishes or a bill is issued." },
];

