        </div>

        <div className="panel overflow-hidden rounded-[24px] shadow-[0_30px_100px_-30px_rgb(0_0_0/0.9)]">
          <div className="flex items-center justify-between border-b border-[var(--line)] pr-2">
            <div role="tablist" aria-label="Code example language" className="flex overflow-x-auto">
