const QUOTES = [
  {
    quote:
      "We moved 40 production servers over a weekend. The API matched our Terraform almost line for line, and our p95 in Europe dropped by a third.",
    name: "Maya Okafor",
    role: "Head of Platform, Ledgerline",
    tag: "Developers",
  },
  {
    quote: "Our Rust server has 180 people on it every wipe day and it doesn't stutter. Support answered a 2 a.m. ticket in six minutes.",
    name: "Tomasz Wrona",
    role: "Admin, Last Light Rust",
    tag: "Gamers",
  },
  {
    quote: "I don't know what a hypervisor is and I don't need to. Our shop has been up through two Black Fridays.",
    name: "Priya Raman",
    role: "Founder, Kettle & Co.",
    tag: "Business",
  },
  {
    quote: "Hourly billing means our preview environments cost pennies. We spin up a server per pull request and tear it down on merge.",
    name: "Jonas Berg",
    role: "Staff Engineer, Northwind Labs",
    tag: "Developers",
  },
  {
    quote: "Installed 140 mods from the list, and the server came back from a crash on its own before anyone on Discord noticed.",
    name: "Alex Kim",
    role: "Runs a 60-player modded SMP",
    tag: "Gamers",
  },
];

export function Testimonials() {
  const [featured, ...rest] = QUOTES;
  return (
    <section aria-labelledby="quotes-title" className="relative py-24 sm:py-32">
      <div className="mx-auto max-w-6xl px-4 sm:px-6">
        <h2 id="quotes-title" className="sr-only">
          What customers say
        </h2>
        <figure className="max-w-4xl">
          <blockquote className="text-balance font-display text-[clamp(1.4rem,3vw,2.3rem)] font-light leading-[1.3] tracking-[-0.02em] text-ink">
            “{featured.quote}”
          </blockquote>
          <figcaption className="mt-6 flex items-center gap-3">
            <Avatar name={featured.name} />
            <span>
              <span className="block text-ink">{featured.name}</span>
              <span className="block text-sm text-haze">{featured.role}</span>
            </span>
          </figcaption>
        </figure>

        <div className="mt-16 grid gap-px overflow-hidden rounded-[24px] border border-[var(--line)] bg-[var(--line)] sm:grid-cols-2 lg:grid-cols-4">
          {rest.map((q) => (
            <figure key={q.name} className="flex flex-col bg-abyss p-6">
              <p className="text-xs text-violet">{q.tag}</p>
              <blockquote className="mt-3 text-pretty text-[15px] leading-relaxed text-mist">“{q.quote}”</blockquote>
              <figcaption className="mt-auto flex items-center gap-3 pt-6">
                <Avatar name={q.name} small />
                <span>
                  <span className="block text-sm text-ink">{q.name}</span>
                  <span className="block text-xs text-haze">{q.role}</span>
                </span>
              </figcaption>
            </figure>
          ))}
        </div>
      </div>
    </section>
  );
}

function Avatar({ name, small = false }: { name: string; small?: boolean }) {
  const initials = name.split(" ").map((p) => p[0]).join("");
  const hue = [...name].reduce((a, c) => a + c.charCodeAt(0), 0) % 60;
  return (
    <span
      aria-hidden="true"
      className={`grid shrink-0 place-items-center rounded-full font-display text-white ${small ? "size-9 text-[11px]" : "size-11 text-xs"}`}
      style={{ background: `linear-gradient(135deg, hsl(${220 + hue} 90% 58%), hsl(${255 + hue} 80% 55%))` }}
    >
      {initials}
    </span>
  );
}

