import { Plus } from "lucide-react";

const FAQS = [
  {
    q: "How fast is a new server ready?",
    a: "Most servers are reachable in 30 to 45 seconds. Game servers take slightly longer on first boot while the game files download, usually under two minutes.",
  },
  {
    q: "Can I move my existing server or game world over?",
    a: "Yes. Upload a disk image or a world folder, or ask support to migrate it for you. Migrations are free for plans of 4 vCPU or more.",
  },
  {
    q: "What happens if I go over my transfer allowance?",
    a: "Extra transfer is $1 per TB, and we email you at 80% so it's never a surprise. Traffic between your servers on the private network is free.",
  },
  {
    q: "Is DDoS protection really included?",
    a: "On every plan, including the $4 one. Filtering is always on, and game servers get game-aware rules that tell real players apart from floods.",
  },
  {
    q: "Do you offer refunds?",
    a: "Billing is hourly, so you only pay for what you use. If something goes wrong on our side, SLA credits are applied automatically.",
  },
  {
    q: "Which payment methods do you accept?",
    a: "Credit and debit cards through Stripe, and PayPal. Business accounts can pay by invoice.",
  },
];

export function FAQ() {
  return (
    <section aria-labelledby="faq-title" className="relative py-24 sm:py-32">
      <div className="mx-auto grid max-w-6xl gap-10 px-4 sm:px-6 lg:grid-cols-[0.8fr_1.2fr]">
        <div>
          <h2 id="faq-title" className="font-display text-[clamp(1.8rem,3.6vw,2.8rem)] font-normal leading-[1.1] tracking-[-0.03em]">
            Questions
          </h2>
          <p className="mt-4 max-w-sm text-pretty text-mist">
            Anything else? Our support team answers in minutes, day and night.{" "}
            <a href="#" className="text-ink underline decoration-violet/60 underline-offset-4 hover:decoration-violet">
              Talk to a person
            </a>
          </p>
        </div>
        <div className="divide-y divide-[var(--line)] border-y border-[var(--line)]">
          {FAQS.map((f) => (
            <details key={f.q} className="group">
              <summary className="flex cursor-pointer list-none items-center justify-between gap-6 py-5 text-[17px] text-ink [&::-webkit-details-marker]:hidden">
                {f.q}
                <Plus className="size-5 shrink-0 text-haze transition-transform duration-300 group-open:rotate-45" />
              </summary>
              <p className="max-w-[62ch] pb-6 pr-10 text-pretty leading-relaxed text-mist">{f.a}</p>
            </details>
          ))}
        </div>
      </div>
    </section>
  );
}

