3	import { useEffect, useRef } from "react";
4	
5	const VERT = `
6	attribute vec2 aPos;
7	void main() { gl_Position = vec4(aPos, 0.0, 1.0); }
8	`;
9	
10	// Three curtains of light drifting over a navy sky. The lowest curtain carries the
11	// teal edge; the upper two stay in the brand blue and violet.
12	const FRAG = `
13	precision highp float;
14	uniform vec2 uRes;
15	uniform float uTime;
16	uniform vec2 uMouse;
17	uniform float uIntensity;
18	
19	float hash(vec2 p) { p = fract(p * vec2(123.34, 456.21)); p += dot(p, p + 45.32); return fract(p.x * p.y); }
20	float noise(vec2 p) {
21	  vec2 i = floor(p), f = fract(p);
22	  vec2 u = f * f * (3.0 - 2.0 * f);
23	  return mix(mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x), mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x), u.y);
24	}
25	float fbm(vec2 p) { float v = 0.0, a = 0.5; for (int i = 0; i < 5; i++) { v += a * noise(p); p *= 2.03; a *= 0.5; } return v; }
26	
27	void main() {
28	  vec2 uv = gl_FragCoord.xy / uRes;
29	  float aspect = uRes.x / uRes.y;
30	  float t = uTime * 0.05;
31	  vec2 m = (uMouse - 0.5) * 0.08;
32	
33	  vec3 sky = mix(vec3(0.016, 0.031, 0.090), vec3(0.035, 0.050, 0.170), smoothstep(0.1, 1.0, uv.y));
34	  vec3 col = sky;
35	
36	  vec3 cBase[3]; vec3 cTop[3];
37	  cBase[0] = vec3(0.23, 0.91, 0.82); cTop[0] = vec3(0.08, 0.44, 1.00);
38	  cBase[1] = vec3(0.08, 0.44, 1.00); cTop[1] = vec3(0.36, 0.18, 0.91);
39	  cBase[2] = vec3(0.55, 0.36, 0.96); cTop[2] = vec3(0.20, 0.10, 0.55);
40	
41	  for (int i = 0; i < 3; i++) {
42	    float fi = float(i);
43	    float x = uv.x * aspect * (0.8 + fi * 0.3) + m.x * (1.0 + fi) + fi * 2.7;
44	    float wave = sin(x * 1.25 + t * (2.0 + fi) + fi) * 0.09
45	               + (fbm(vec2(x * 0.7 - t * 0.8, fi * 3.0 + t * 0.3)) - 0.5) * 0.28;
46	    float center = 0.56 + fi * 0.09 + wave + m.y;
47	    float d = uv.y - center;
48	    float edge = smoothstep(-0.05 - fi * 0.01, 0.0, d);
49	    float fall = exp(-max(d, 0.0) * (5.5 - fi * 1.2));
50	    float rays = 0.35 + 0.65 * fbm(vec2(x * 11.0 + t * 1.5, uv.y * 0.9 - t * 2.0 + fi));
51	    float glow = edge * fall * rays;
52	    vec3 c = mix(cBase[i], cTop[i], clamp(d * 3.0, 0.0, 1.0));
53	    col += c * glow * (0.55 - fi * 0.1) * uIntensity;
54	  }
55	
56	  // sparse stars, dimmed where the aurora is bright
57	  vec2 sg = floor(gl_FragCoord.xy / 7.0);
58	  vec2 sf = fract(gl_FragCoord.xy / 7.0) - 0.5 - (vec2(hash(sg + 1.3), hash(sg + 2.1)) - 0.5) * 0.5;
59	  float s = step(0.975, hash(sg)) * smoothstep(0.2, 0.0, length(sf));
60	  float tw = 0.5 + 0.5 * sin(uTime * 1.3 + hash(sg + 7.0) * 40.0);
61	  col += s * tw * 0.55 * smoothstep(0.35, 0.9, uv.y) * (1.0 - clamp(length(col - sky) * 2.0, 0.0, 1.0));
62	
63	  // settle into the page colour at the bottom edge
64	  col = mix(vec3(0.016, 0.031, 0.090), col, smoothstep(0.0, 0.42, uv.y));
65	  gl_FragColor = vec4(col, 1.0);
66	}
67	`;
68	
69	type Props = { className?: string; intensity?: number };
70	
71	export function Aurora({ className = "", intensity = 1 }: Props) {
72	  const ref = useRef<HTMLCanvasElement>(null);
73	
74	  useEffect(() => {
75	    const canvas = ref.current;
76	    if (!canvas) return;
77	    const gl = canvas.getContext("webgl", { antialias: false, premultipliedAlpha: false, powerPreference: "low-power" });
78	    if (!gl) return;
79	
80	    const compile = (type: number, src: string) => {
81	      const s = gl.createShader(type)!;
82	      gl.shaderSource(s, src);
83	      gl.compileShader(s);
84	      return s;
85	    };
86	    const prog = gl.createProgram()!;
87	    gl.attachShader(prog, compile(gl.VERTEX_SHADER, VERT));
88	    gl.attachShader(prog, compile(gl.FRAGMENT_SHADER, FRAG));
89	    gl.linkProgram(prog);
90	    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) return;
91	    gl.useProgram(prog);
92	
93	    const buf = gl.createBuffer();
94	    gl.bindBuffer(gl.ARRAY_BUFFER, buf);
95	    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
96	    const loc = gl.getAttribLocation(prog, "aPos");
97	    gl.enableVertexAttribArray(loc);
98	    gl.vertexAttribPointer(loc, 2, gl.FLOAT, false, 0, 0);
99	
100	    const uRes = gl.getUniformLocation(prog, "uRes");
101	    const uTime = gl.getUniformLocation(prog, "uTime");
102	    const uMouse = gl.getUniformLocation(prog, "uMouse");
103	    gl.uniform1f(gl.getUniformLocation(prog, "uIntensity"), intensity);
104	
105	    // The aurora is soft by nature, so render at reduced resolution and let CSS scale it.
106	    const scale = 0.5;
107	    const resize = () => {
108	      const w = Math.max(1, Math.floor(canvas.clientWidth * scale));
109	      const h = Math.max(1, Math.floor(canvas.clientHeight * scale));
110	      canvas.width = w;
111	      canvas.height = h;
112	      gl.viewport(0, 0, w, h);
113	      gl.uniform2f(uRes, w, h);
114	    };
115	    resize();
116	    const ro = new ResizeObserver(resize);
117	    ro.observe(canvas);
118	
119	    const mouse = { x: 0.5, y: 0.5, tx: 0.5, ty: 0.5 };
120	    const onMove = (e: PointerEvent) => {
121	      mouse.tx = e.clientX / window.innerWidth;
122	      mouse.ty = 1 - e.clientY / window.innerHeight;
123	    };
124	    window.addEventListener("pointermove", onMove, { passive: true });
125	
126	    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
127	    let visible = true;
128	    const io = new IntersectionObserver(([entry]) => (visible = entry.isIntersecting));
129	    io.observe(canvas);
130	
131	    let raf = 0;
132	    const start = performance.now();
133	    const frame = (now: number) => {
134	      raf = requestAnimationFrame(frame);
135	      if (!visible) return;
136	      mouse.x += (mouse.tx - mouse.x) * 0.03;
137	      mouse.y += (mouse.ty - mouse.y) * 0.03;
138	      gl.uniform1f(uTime, reduced ? 12 : (now - start) / 1000);
139	      gl.uniform2f(uMouse, mouse.x, mouse.y);
140	      gl.drawArrays(gl.TRIANGLES, 0, 3);
141	      if (reduced) cancelAnimationFrame(raf);
142	    };
143	    raf = requestAnimationFrame(frame);
144	
145	    return () => {
146	      cancelAnimationFrame(raf);
147	      ro.disconnect();
148	      io.disconnect();
149	      window.removeEventListener("pointermove", onMove);
150	      gl.getExtension("WEBGL_lose_context")?.loseContext();
151	    };
152	  }, [intensity]);
153	
154	  return (
155	    <div className={`pointer-events-none absolute inset-0 ${className}`} aria-hidden="true">
156	      {/* CSS fallback, visible until (or if) WebGL paints */}
157	      <div className="absolute inset-0 bg-[radial-gradient(80%_60%_at_30%_20%,rgb(21_112_255/0.25),transparent_60%),radial-gradient(60%_50%_at_75%_10%,rgb(139_92_246/0.28),transparent_60%)]" />
158	      <canvas ref={ref} className="absolute inset-0 h-full w-full" />
159	    </div>
160	  );
161	}

