55	function highlight(code: string) {
56	  const re = /((?<=^|\s)(?:#|\/\/)[^\n]*)|("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')|(\s--?[a-z][\w-]*)|\b(import|from|const|await|new|resource|terraform|required_providers|curl|nx)\b|(\$\w+)/g;
57	  const out: React.ReactNode[] = [];
58	  let last = 0;
59	  let m: RegExpExecArray | null;
60	  let i = 0;
61	  while ((m = re.exec(code))) {
62	    if (m.index > last) out.push(code.slice(last, m.index));
63	    const [t] = m;
64	    const cls = m[1] ? "text-haze italic" : m[2] ? "text-[#9ee6d9]" : m[3] ? "text-nx-soft" : m[4] ? "text-[#c4a8ff]" : "text-[#f5c07a]";
65	    out.push(<span key={i++} className={cls}>{t}</span>);
66	    last = m.index + t.length;
67	  }
68	  out.push(code.slice(last));
69	  return out;
70	}
